\label{Def:2.2}
	A family $K=\{K(\tau):\tau\in\mathbb{R}\}\in\mathcal{D}$ is called a $\mathcal{D}$-pullback absorbing set for $S$ if for each $\tau\in\mathbb{R}$ and every $D\in\mathcal{D}$, there exists $T=T(\tau,D)>0$ such that
		\begin{align*}
		S(t,\tau-t)D(\tau-t)\subseteq K(\tau),\ \forall\ t\geq T.
	\end{align*}

\label{Def:2.4}
	A family $\mathcal{A}=\{\mathcal{A}(\tau):\tau\in\mathbb{R}\}\in\mathcal{D}$ is called a $\mathcal{D}$-pullback measure attractor for $S$ if the following conditions are satisfied:\par
	$(\mathbf{i})\ \mathcal{A}(\tau)$ is compact in $\mathcal{P}_{p}(X)$ for each $\tau\in\mathbb{R}$;\par
	$(\mathbf{ii})\ \mathcal{A}$ is invariant, that is, $S(t,\tau)\mathcal{A}(\tau)=\mathcal{A}(\tau+t)$, for all $\tau\in\mathbb{R}$ and $t\in\mathbb{R}^+$;\par
	$(\mathbf{iii})\ \mathcal{A}$ attracts every set in $\mathcal{D}$, that is, for each $D=\{D(\tau):\tau\in\mathbb{R}\}\in\mathcal{D}$,
	\begin{align*}
		\lim_{t\to\infty}d_{\mathcal{P}_{p}(X)}(S(t,\tau-t)D(\tau-t),\mathcal{A}(\tau))=0,
	\end{align*}
	where $d_{\mathcal{P}_{p}(X)}(\cdot,\cdot)$ denotes the Hausdorff semi-metric between any two subsets of $\mathcal{P}_{p}(X)$.

\label{Def:2.6}
	Suppose $\tau\in\mathbb{R}$, and $\Phi_{\tau}=\binom{u_{\tau}}{v_{\tau}}\in L^2_{\mathcal{F}_{\tau}}(\Omega,\ell^2\times\ell^2)$ is $\mathcal{F}_{\tau}$-measurable. Then, a continuous $\ell^2\times\ell^2$-valued stochastic process $\Phi(t)=\binom{u(t)}{v(t)}$ with $t\in [\tau, \infty)$ is called a strong solution of \eqref{eq:2.16} with initial data $\Phi_{\tau}$ if $(\Phi_t)_{t\geq \tau}$ is $\mathcal{F}_{t}$-adapted, $\Phi(t)\in L^2(\Omega,C([\tau,T],\ell^2\times\ell^2)$ for all $T>\tau$ and for each $\tau\leq t\leq T$, $\Phi(t)=\binom{u(t)}{v(t)}$ satisfies
\begin{equation}\label{eq:2.17}
	u(t)=u_{\tau}+\int_{\tau}^{t}(v(r)-\delta u(r))dr,
\end{equation}	
\begin{equation}\label{eq:2.18}
	\begin{aligned}
			v(t)=&v_{\tau}+\int_{\tau}^{t}\left(-(\lambda+\delta^2-\alpha \delta)u(r)-(\alpha-\delta)v(r)-\nu Au(r)+f(r,u(r),\mathcal{L}_{u(r)})+g(r)\right)dr\\&+\int_{\tau}^{t}(\tilde{\sigma}(r, u(r),\mathcal{L}_{u(r)}))dW(r).
	\end{aligned}
\end{equation}

\label{Def:2.7}
	For any $\mu_\tau \in \mathcal{P}_2(\mathbb{R})$, $(\tilde{\Phi}(t))_{t \ge \tau}, (\tilde{W}(t))_{t \ge \tau}$ is called a weak solution to \eqref{eq:2.16} starting at $\mu_\tau$, if $(\tilde{W}(t))_{t \ge \tau}$ is a cylindrical $Q$-Wiener process with $Q = I$ under a stochastic basis $(\tilde{\Omega}, \tilde{\mathcal{F}}, \{\tilde{\mathcal{F}}_t\}_{t \ge \tau}, \tilde{\mathbb{P}})$ (i.e. a complete probability space with normal filtration), and $(\tilde{\Phi}(t))_{t \ge \tau}$ is a $\mathcal{F}_t$-adapted $\ell^2\times\ell^2$-valued stochastic process with $\mathcal{L}_{\tilde{u}_\tau}|_{\tilde{\mathbb{P}}} = \mu_\tau$, $\tilde{\Phi}=\binom{\tilde{u}}{\tilde{v}} \in L^2(\Omega, C([\tau, T], \ell^2\times\ell^2))$ for any $T > \tau$ and for each $\tau\leq t\leq T$, $\tilde{\Phi}(t)=\binom{\tilde{u}(t)}{\tilde{v}(t)}$ satisfies
	\begin{equation}\label{eq:2.19}
		\tilde{u}(t)=\tilde{u}_{\tau}+\int_{\tau}^{t}(\tilde{v}(r)-\delta \tilde{u}(r))dr,
	\end{equation}	
	\begin{equation}\label{eq:2.20}
		\begin{aligned}
			\tilde{v}(t)=&\tilde{v}_{\tau}+\int_{\tau}^{t}\left(-(\lambda+\delta^2-\alpha \delta)\tilde{u}(r)-(\alpha-\delta)\tilde{v}(r)-\nu A\tilde{u}(r)+f(r,\tilde{u}(r),\mathcal{L}_{\tilde{u}(r)})+g(r)\right)dr\\&+\int_{\tau}^{t}(\tilde{\sigma}(r, \tilde{u}(r),\mathcal{L}_{\tilde{u}(r)}))d\tilde{W}(r).
		\end{aligned}
	\end{equation}

\label{pro:3.1}
Suppose $\tau\in\mathbb{R}$, and $\Phi_{\tau}=\binom{u_{\tau}}{v_{\tau}}\in L^2_{\mathcal{F}_{\tau}}(\Omega,\ell^2\times\ell^2)$ is $\mathcal{F}_{\tau}$-measurable. If $(A1)-(A3)$ hold, then
system \eqref{eq:2.16} has a unique stong solution  $\Phi=\binom{u}{v}\in L^2(\Omega,C([\tau,T]),\ell^2\times\ell^2)$ for every $T>\tau$ with the property $\mathcal{L}_{\Phi_{(t)}}\in\mathcal{P}^2(\ell^2\times\ell^2)$ for all $\tau\leq t\leq T$. In addition, in this context,uniqueness means that any other solution $\Psi$ of system \eqref{eq:2.16} is indistinguishable from $\Phi$, i.e.,:
\begin{align*}
\mathbb{P}\left(\left\{\Phi(t)=\Psi(t),\forall t\in [\tau,T]\right\}\right)=1. 
\end{align*}

The proof is carried out in three steps by means of the Picard iteration method.\par
\textbf{Step1:} First,we prove the existence. For all $\tau\leq t\leq T$, let $\Phi^{(0)}(t)=\binom{u^{(0)}(t)}{v^{(0)}(t)}=\binom{u_{\tau}}{v_{\tau}}$, $\mathcal{L}_{u^{(0)}(t)}=\mathcal{L}_{u_{\tau}}$. For any $n\in\mathbb{N}^+$, let $\Phi^{(n)}(t)=\binom{u^{(n)}(t)}{v^{(n)}(t)}$ solve the following integral equation	
\begin{equation}\label{eq:3.1}
	\left\{
	\begin{aligned}
		u^{(n)}(t)=&u_{\tau}+\int_{\tau}^{t}v^{(n-1)}(s)ds-\delta \int_{\tau}^{t}u^{(n-1)}(s)ds,\\		
		v^{(n)}(t)=&v_{\tau}-(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}u^{(n-1)}(s)ds-(\alpha-\delta)\int_{\tau}^{t}v^{(n-1)}(s)ds-\nu \int_{\tau}^{t}Au^{(n-1)}(s)ds\\&+\int_{\tau}^{t}f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})ds+\int_{\tau}^{t}g(s)ds+\int_{\tau}^{t}\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})dW(s)
	\end{aligned}
	\right.
\end{equation}
with initial condition $\binom{u^{(n)}_{\tau}}{v^{(n)}_{\tau}}=\binom{u_{\tau}}{v_{\tau}}$, so $\binom{u^{(n)}}{v^{(n)}}\in L^2(\Omega,C([\tau,\tau+T]),\ell^2\times\ell^2)$ foe each $n\in\mathbb{N}$.\par
Next, we will show that for all $n\in\mathbb{N}^+$ and $\tau\leq t\leq T$,
\begin{align}\label{eq:3.2}
	\mathbb{E}\{\sup_{\tau\leq\varrho\leq t}\|\Phi^{(n)}(\varrho)\|^2\}\leq\left[\bigstar_1+\bigstar_2(T-\tau)\mathbb{E}\|\Phi_{\tau}\|^2\right]e^{\bigstar_2T},
\end{align}
where $\bigstar_1$ and $\bigstar_2$ are positive constants independent of $n$ and $t$.\\
By \eqref{eq:3.1}, we have for any $n\in\mathbb{N}^+$ and $\tau\leq t\leq T$,
\begin{equation*}
	\left\{
	\begin{aligned}
		\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|u^{(n)}(\varrho)\|^2)=&3\|u_{\tau}\|^2+3\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\varrho}v^{(n-1)}(s)ds\|^2)+3\delta^2 \mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\rho}u^{(n-1)}(s)ds\|^2),\\		
		\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|v^{(n)}(\varrho)\|^2)=&7\|v_{\tau}\|^2+7(\lambda+\delta^2-\alpha \delta)^2\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\varrho}u^{(n-1)}(s)ds\|^2)\\&+7(\alpha-\delta)^2\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\varrho}v^{(n-1)}(s)ds\|^2)+7\nu^2\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\| \int_{\tau}^{\varrho}Au^{(n-1)}(s)ds\|^2)\\&+7\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\varrho}f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})ds\|^2\\&+7\mathbb{E}(\sup_{\tau\leq\rho\leq t}\|\int_{\tau}^{\varrho}g(s)ds\|^2+7\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\int_{\tau}^{\varrho}\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})dW(s)\|^2.
	\end{aligned}
	\right.
\end{equation*}
By using \eqref{eq:2.8}, \eqref{eq:2.13}, \eqref{eq:2.14} and the BDG inequality, we get that
\begin{align*}
	\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\Phi^{(n)}(\varrho)\|^2)\leq&7\|\Phi_{\tau}\|^2+7[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+1](T-\tau)\int_{\tau}^{t}\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|\Phi^{(n-1)}(\varrho)\|^2)ds\\&+[(2\nu^2+42\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)})(T-\tau)+56c_1\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}]\int_{\tau}^{t}\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|u^{(n-1)}(\varrho)\|^2)ds\\&+[21(T-\tau)\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+7\int_{\tau}^{T}\|g(s)\|^2ds+14c_1\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}](T-\tau)\\\leq&\bigstar_1+\bigstar_2\int_{\tau}^{t}\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|\Phi^{(n-1)}(\varrho)\|^2)ds,
\end{align*}
where $c_1$ follows from the BDG inequality. Thus we obtain that for any $m\in\mathbb{N}^+$ and $\tau\leq t\leq T$,
\begin{align*}
	\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\Phi^{(n)}(\varrho)\|^2)]\leq\bigstar_1+\bigstar_2\int_{\tau}^{t}\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|\Phi^{(n-1)}(\varrho)\|^2)]ds,
\end{align*}
which implies,
\begin{align*}
	\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\Phi^{(n)}(\varrho)\|^2)]&\leq\bigstar_1+\bigstar_2\int_{\tau}^{t}\left(\mathbb{E}\|\Phi_{\tau}\|^2+\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|\Phi^{(n)}(\varrho)\|^2)]\right)ds\\&\leq\bigstar_1+\bigstar_2(T-\tau)\mathbb{E}\|\Phi_{\tau}\|^2+\bigstar_2\int_{\tau}^{t}\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq s}\|\Phi^{(n)}(\varrho)\|^2)]ds.
\end{align*}
Utilizing the Gronwall inequality, we have that for any $m\in\mathbb{N}^+$ and $\tau\leq t\leq T$,
\begin{align*}
	\sup_{1\leq n\leq m}[\mathbb{E}(\sup_{\tau\leq\varrho\leq t}\|\Phi^{(n)}(\varrho)\|^2)]\leq\left[\bigstar_1+\bigstar_2(T-\tau)\mathbb{E}\|\Phi_{\tau}\|^2\right]e^{\bigstar_2T},
\end{align*}
then by the arbitrariness of $m$, \eqref{eq:3.2} holds.\par
To make the notation simpler, we denote $\Xi^{(n)}(t)=\binom{a^{(n)}(t)}{b^{(n)}(t)}:=\Phi^{(n+1)}(t)-\Phi^{(n)}(t)=\binom{u^{(n+1)}(t)-u^{(n)}(t)}{v^{(n+1)}(t)-v^{(n)}(t)}$ for all $n\in\mathbb{N}$ and $t\in[\tau,T]$. It's clear that $\|\Xi^{(n)}(t)\|^2=\|a^{(n)}(t)\|^2+\|b^{(n)}(t)\|^2$. As $n=0$, $\Xi^{(0)}(t):=\Phi^{(1)}(t)-\Phi_{\tau}$. Let

\begin{align*}
	M:=&8(T-\tau)\{[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+16\nu^2+1]+6\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}(T-\tau)\\&+8c_1\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}(T-\tau)\}\mathbb{E}\|\Phi_{\tau}\|^2\\&+8(T-\tau)\{3\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}(T-\tau)+\int_{\tau}^{T}\|g(s)\|^2ds+2c_1\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}\}
\end{align*}
and
\begin{align*}
	N:=7(T-\tau)\{[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+16\nu^2+1]+4\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}\}+28c_1\|\kappa \|^2_{L^\infty(\mathbb{R},\ell^2)}.
\end{align*}
Our initial inductive claim states that for every $ n \in \mathbb{N} $ and $ \tau \leq t \leq T $,
\begin{align}\label{eq:3.3}
 \mathbb{E}\left(\sup_{\tau \leq \varrho \leq t} \|\Xi^{(n)}(\varrho)\|^2\right) \leq \frac{M[N(t - \tau)]^n}{n!}.
\end{align}
We now proceed to verify this claim. In fact, when $ n = 0 $, it follows that for all $ \tau \leq t \leq T $,
\begin{equation*}
	\left\{
	\begin{aligned}
		u^{(1)}(t)=&u_{\tau}+\int_{\tau}^{t}v^{(0)}(s)ds-\delta \int_{\tau}^{t}u^{(0)}(s)ds,\\		
		v^{(1)}(t)=&v_{\tau}-(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}u^{(0)}(s)ds-(\alpha-\delta)\int_{\tau}^{t}v^{(0)}(s)ds-\nu \int_{\tau}^{t}Au^{(0)}(s)ds\\&+\int_{\tau}^{t}f(s,u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})ds+\int_{\tau}^{t}g(s)ds+\int_{\tau}^{t}\tilde{\sigma}(s, u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})dW(s)
	\end{aligned}
	\right.
\end{equation*}
Along with \eqref{eq:2.10}, we obtain that for all $ \tau \leq t \leq T $,
\begin{align*}
	\mathbb{E}\left(\sup_{\tau \leq \varrho \leq t} \|\Xi^{(n)}(\varrho)\|^2\right) \leq&6(T-\tau)^2[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+16\nu^2+1]\mathbb{E}\|\Phi_{\tau}\|^2\\&+6(T-\tau)\int_{\tau}^{T}\|g(s)\|^2ds\\&+6(T-\tau)\int_{\tau}^{t}\mathbb{E}\|f(s,u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})\|^2ds\\&+6\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\int_{\tau}^{\varrho}\tilde{\sigma}(s, u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})dW(s) ).
\end{align*}
By using \eqref{eq:2.8} and \eqref{eq:2.13},  we find that for all $ \tau \leq t \leq T $,
\begin{align*}
&6(T-\tau)\int_{\tau}^{t}\mathbb{E}\|f(s,u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})\|^2ds\\\leq&18(T-\tau)\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}[(T-\tau)+2(T-\tau)\mathbb{E}\|u_{\tau}\|^2].
\end{align*}
By \eqref{eq:2.8}, \eqref{eq:2.14} and the BDG inequality, we have  that for all $ \tau \leq t \leq T $,
\begin{align*}
	&6\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\int_{\tau}^{\varrho}\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})dW(s) )\\\leq&6c_1\mathbb{E}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u^{(0)}(s),\mathcal{L}_{u^{(0)}(s)})\|^2_{L_2(\ell^2,\ell^2)})\\\leq&48c_1(T-\tau)\|\kappa \|^2_{L^\infty(\mathbb{R},\ell^2)}\mathbb{E}\|u_{\tau}\|^2+12c_1(T-\tau)\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)},
\end{align*}
where $c_1$ follows from the BDG inequality. Given the preceding reasoning, \eqref{eq:3.3} is valid for $n=0$. Next, suppose that \eqref{eq:3.3}  holds for $k=n-1$. In order to establish the statement for $k=n$, we begin by noting that for all $ \tau \leq t \leq T $ that
\begin{equation*}
	\left\{
	\begin{aligned}
		a^{(n)}(t)=&\int_{\tau}^{t}b^{(n-1)}(s)ds-\delta \int_{\tau}^{t}a^{(n-1)}(s)ds,\\		
		b^{(n)}(t)=&-(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}a^{(n-1)}(s)ds-(\alpha-\delta)\int_{\tau}^{t}b^{(n-1)}(s)ds-\nu \int_{\tau}^{t}Aa^{(n-1)}(s)ds\\&+\int_{\tau}^{t}[f(s,u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})]ds\\&+\int_{\tau}^{t}[\tilde{\sigma}(s, u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})]dW(s).
	\end{aligned}
	\right.
\end{equation*}
Then, we have  that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.4}
	\begin{aligned}
		\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\Xi^{(n)}(\varrho)\|^2)\leq&5(T-\tau)[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+16\nu^2+1]\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\Xi^{(n-1)}(\varrho)\|^2)ds\\&+5(T-\tau)\int_{\tau}^{t}\mathbb{E}\|f(s,u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})\|^2ds\\&+5\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}[\tilde{\sigma}(s, u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})]dW(s)\|^2).
	\end{aligned}
\end{equation}
For the second term in the right-hand side of \eqref{eq:3.4}, by using \eqref{eq:2.8} and  \eqref{eq:2.11},  we find that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.5}
	\begin{aligned}
	&5(T-\tau)\int_{\tau}^{t}\mathbb{E}\|f(s,u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})\|^2ds\\\leq&	20(T-\tau)\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho \leq s}\|a^{(n-1)}(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
For the last term in the right-hand side of \eqref{eq:3.4}, by using the BDG inequality, \eqref{eq:2.8} and  \eqref{eq:2.12},  we find that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.6}
	\begin{aligned}
		&5\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}[\tilde{\sigma}(s, u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})]dW(s)\|^2)\\\leq&5c_1\mathbb{E}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u^{(n)}(s),\mathcal{L}_{u^{(n)}(s)})-\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})\|_{L_2(\ell^2,\ell^2)}^2ds)\\\leq&20c_1\|\kappa \|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho \leq s}\|a^{(n-1)}(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
Considering \eqref{eq:3.4}-\eqref{eq:3.6}, from the induction hypothesis, it follows that for all $ t \in [\tau, T] $,
\begin{align*}
	\mathbb{E}(\sup_{\tau \leq \varrho
		 \leq t} \|\Xi^{(n)}(\varrho)\|^2) \leq N\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho
		 \leq t} \|\Xi^{(n-1)}(\varrho)\|^2)\leq N \int_\tau^t \frac{M[N(s-\tau)]^{n-1}}{(n-1)!} ds = \frac{M[N(t - \tau)]^n}{n!}.
\end{align*}
Hence, statement \eqref{eq:3.3} holds for every $ n \in \mathbb{N} $.\par
Applying Chebyshev's inequality yields
\begin{align*}
	\mathbb{P}(\sup_{\tau \leq \varrho \leq T} \|\Xi^{(n)}(\varrho)\| > \frac{1}{2^n}) \leq \frac{M(4NT)^n}{n!}.
\end{align*}
Due to the convergence of the positive series $	\sum_{n=0}^\infty \frac{M(4NT)^n}{n!}$
along with the Borel-Cantelli lemma, for almost every $ \omega \in \Omega $ one can find a positive integer $ N = N(\omega) $ such that for every $ n > N $,
\begin{align*} 
	\sup_{\tau \leq \varrho \leq T} \|\Xi^{(n)}(\varrho)\| \leq \frac{1}{2^n},
\end{align*}
which implies that the partial sum sequence
\begin{align*} 
	\Phi^{(n)}(t)=\Phi^{(0)} + \sum_{k=0}^{n-1}\Xi^{(k)}(t) 
\end{align*}
converges uniformly for $ t \in [\tau, T] $ for almost every $ \omega \in \Omega $.  
Let the limit be denoted by $ \Phi(t)=\binom{u(t)}{v(t)} $ for $ t \in [\tau, T] $.
Evidently, $ \Phi $ is $ \mathcal{F}_t $-adapted when $ t \geq \tau $.  
Additionally, using \eqref{eq:3.2} and the dominated convergence theorem, we obtain
\begin{align} \label{eq:3.7}
	\mathbb{E} \left( \sup_{\tau \leq \varrho \leq T} \|\Phi^{(n)}(\varrho) - \Phi(\varrho)\|^2 \right) \to 0, \quad \text{as } n \to \infty.
\end{align}\par
To confirm that $ \Phi(t) $ satisfies equation \eqref{eq:2.16}, by virtue of \eqref{eq:2.10} and \eqref{eq:3.7}, we derive for each $ t \in [\tau, T] $ that
\begin{equation}\label{eq:3.8}
	\begin{aligned}
		\mathbb{E}(&\|\int_{\tau}^{t}(v^{(n-1)}(s)-v(s))ds-\delta\int_{\tau}^{t}(u^{(n-1)}(s)-u(s))ds-(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}(u^{(n-1)}(s)-u(s))d\\&-s(\alpha-\delta)\int_{\tau}^{t}(v^{(n-1)}(s)-v(s))ds-\nu\int_{\tau}^{t}A(u^{(n-1)}(s)-u(s))ds\|^2)\\\leq&5(T-\tau)[(\lambda+\delta^2-\alpha \delta)^2+(\alpha-\delta)^2+\delta^2+16\nu^2+1]\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho \leq s}\|\Phi^{(n-1)}(\varrho) - \Phi(\varrho)\|^2)ds\\\to& 0, \quad \text{as } n \to \infty.
	\end{aligned}
\end{equation}
By using \eqref{eq:2.8}, \eqref{eq:2.11}, \eqref{eq:2.12} and \eqref{eq:3.7}, we find for each $ t \in [\tau, T] $,
\begin{equation}\label{eq:3.9}
	\begin{aligned}
		&\mathbb{E}\|\int_{\tau}^{t}[f(s,u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})-f(s,u(s),\mathcal{L}_{u(s)})]ds\|^2\\&+\mathbb{E}\|\int_{\tau}^{t}[\tilde{\sigma}(s, u^{(n-1)}(s),\mathcal{L}_{u^{(n-1)}(s)})-\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})]dW(s)\|^2\\\leq&\left[2(T-\tau)\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}+4c_1\|\kappa \|^2_{L^\infty(\mathbb{R},\ell^2)}\right]\int_{\tau}^{t}\mathbb{E}(\sup_{\tau \leq \varrho \leq s}\|\Phi^{(n-1)}(\varrho) - \Phi(\varrho)\|^2)ds\\\to& 0, \quad \text{as } n \to \infty.
	\end{aligned}
\end{equation}
Together with \eqref{eq:3.8} and \eqref{eq:3.9}, it follows that $ \Phi $ satisfies \eqref{eq:2.17}-\eqref{eq:2.18} by taking the limit $ n \to \infty $ in \eqref{eq:3.1}. Furthermore, by virtue of \eqref{eq:3.7}, one can choose $ N_0 > 0 $ satisfying
\begin{align*}
	\mathbb{E} \left( \sup_{\tau \leq \varrho \leq T} \|\Phi^{(N_0)}(\varrho) - \Phi(\varrho)\|^2 \right) < \frac{1}{2}.
\end{align*}
Applying \eqref{eq:3.2} once more yields
\begin{equation}\label{eq:3.10}
\begin{aligned}
	\mathbb{E} (\sup_{\tau \leq \varrho \leq T} \|\Phi(\varrho)\|^2 )&\leq 2\mathbb{E} (\sup_{\tau \leq \varrho \leq T} \|\Phi^{(N_0)}(\varrho) - \Phi(\varrho)\|^2) + 2\mathbb{E}( \sup_{\tau \leq \varrho \leq T} \|\Phi^{(N_0)}(\varrho)\|^2) \\
	&\leq 1 + 2(\bigstar_1 + \bigstar_2(T - \tau)\mathbb{E}\|\Phi_{\tau}\|^2)e^{\bigstar_2T}. 
\end{aligned}
\end{equation}
Hence $\Phi\in L^2(\Omega,C([\tau,T],\ell^2\times\ell^2))$.\par
\textbf{Step2:} Next, we prove the uniqueness. Let $\Phi(t)=\binom{u(t)}{v(t)}$ and $\Phi_1(t)=\binom{u_1(t)}{v_1(t)}$ be two strong solutions of \eqref{eq:2.16} in $\Phi\in L^2(\Omega,C([\tau,T],\ell^2\times\ell^2))$. For any $ \tau \leq t \leq T $, notice that
\begin{equation*}
	\left\{
	\begin{aligned}
		u(t)-u_1(t)=&\int_{\tau}^{t}(v(s)-v_1(s))ds-\delta \int_{\tau}^{t}(u(s)-u_1(s))ds,\\		
		v(t)-v_1(t)=&-(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}(u(s)-u_1(s))ds-(\alpha-\delta)\int_{\tau}^{t}(v(s)-v_1(s))ds\\&-\nu \int_{\tau}^{t}A(u(s)-u_1(s))ds+\int_{\tau}^{t}[f(s,u(s),\mathcal{L}_{u(s)})-f(s,u_1(s),\mathcal{L}_{u_1(s)})]ds\\&+\int_{\tau}^{t}[\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})]dW(s).
	\end{aligned}
	\right.
\end{equation*}
Applying the $It\hat{o}$ formula, we get that for all $ \tau \leq t \leq T $,
\begin{equation*}
	\begin{aligned}
		\|u(t)-u_1(t)\|^2=2\int_{\tau}^{t}(u(s)-u_1(s),v(s)-v_1(s))ds-2\delta \int_{\tau}^{t}\|u(s)-u_1(s)\|^2ds,\\		
	\end{aligned}
\end{equation*}
and
\begin{equation*}
	\begin{aligned}		
		\|v(t)-v_1(t)\|^2=&-2(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}(u(s)-u_1(s),v(s)-v_1(s))ds-2(\alpha-\delta)\int_{\tau}^{t}\|v(s)-v_1(s)\|^2ds\\&-2\nu \int_{\tau}^{t}(A(u(s)-u_1(s)),v(s)-v_1(s))ds\\&+2\int_{\tau}^{t}(v(s)-v_1(s),f(s,u(s),\mathcal{L}_{u(s)})-f(s,u_1(s),\mathcal{L}_{u_1(s)}))ds\\&+2\int_{\tau}^{t}(v(s)-v_1(s),[\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})]dW(s))\\&+\int_{\tau}^{t}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds.
	\end{aligned}
\end{equation*}
Therefore, we have
\begin{equation}\label{eq:3.11}
	\begin{aligned}
		&\mathbb{E}\{\sup_{\tau \leq \varrho \leq t}[(\lambda+\delta^2-\alpha \delta)\|u(\varrho)-u_1(\varrho)\|^2+\|v(\varrho)-v_1(\varrho)\|^2]\}\\\leq&2\nu\left|\int_{\tau}^{t}\mathbb{E}(A(u(s)-u_1(s)),v(s)-v_1(s))ds\right|\\&+2\int_{\tau}^{t}\mathbb{E}(v(s)-v_1(s),f(s,u(s),\mathcal{L}_{u(s)})-f(s,u_1(s),\mathcal{L}_{u_1(s)}))ds\\&+\int_{\tau}^{t}\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds\\&+2\mathbb{E}\{\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}(v(s)-v_1(s),[\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})]dW(s))\|\}.
	\end{aligned}
\end{equation}
We estimate each term in the right-hand side of \eqref{eq:3.11} individually. For the first term, employing \eqref{eq:2.9} and \eqref{eq:2.10} yields that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.12}
	\begin{aligned}
		&2\nu\left|\int_{\tau}^{t}\mathbb{E}(A(u(s)-u_1(s)),v(s)-v_1(s))ds\right|\\\leq&2\nu\int_{\tau}^{t}\mathbb{E}\|B(u(s)-u_1(s))\|\|B(v(s)-v_1(s))\|ds\\\leq&\nu\int_{\tau}^{t}\mathbb{E}(\|B(u(s)-u_1(s))\|^2+\|B(v(s)-v_1(s))\|^2)ds\\\leq&4\nu\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
For the second term, we infer from \eqref{eq:2.11} and \eqref{eq:2.8} that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.13}
	\begin{aligned}
		&2\int_{\tau}^{t}\mathbb{E}(v(s)-v_1(s),f(s,u(s),\mathcal{L}_{u(s)})-f(s,u_1(s),\mathcal{L}_{u_1(s)}))ds\\\leq&\int_{\tau}^{t}\mathbb{E}\|v(s)-v_1(s)\|^2ds+\int_{\tau}^{t}\mathbb{E}\|f(s,u(s),\mathcal{L}_{u(s)})-f(s,u_1(s),\mathcal{L}_{u_1(s)})\|^2ds\\\leq&\int_{\tau}^{t}\mathbb{E}\|v(s)-v_1(s)\|^2ds+4\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}\|u(s)-u_1(s)\|^2ds\\\leq&(1+4\|\psi\|^2_{L^\infty([\tau,T],\ell^2)})\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
For the third term, by \eqref{eq:2.12} and \eqref{eq:2.8}, we get that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.14}
	\begin{aligned}
		&\int_{\tau}^{t}\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds\\\leq&\int_{\tau}^{t}2\|\kappa(s)\|^2\mathbb{E}(\|u(s)-u_1(s)\|^2+\mathbb{E}\|u(s)-u_1(s)\|^2)ds\\\leq&4\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
For the last term, by using the BDG inequality and \eqref{eq:3.13}, we obtain that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.15}
	\begin{aligned}
		&2\mathbb{E}\{\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}(v(s)-v_1(s),[\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})]dW(s))\|\}
		\\\leq&2c_1\mathbb{E}\{\int_{\tau}^{t}\|(v(s)-v_1(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)}))\|^2ds\}^{\frac{1}{2}}
		\\\leq&2c_1\mathbb{E}\{\int_{\tau}^{t}\|v(s)-v_1(s)\|^2\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds\}^{\frac{1}{2}}
		\\\leq&2c_1\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)-v_1(\varrho)\|^2)^{\frac{1}{2}}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds)^{\frac{1}{2}}
		\\\leq&\frac{1}{2}\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)-v_1(\varrho)\|^2)+2c_1^2\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})-\tilde{\sigma}(s, u_1(s),\mathcal{L}_{u_1(s)})\|^2_{L_2(\ell^2,\ell^2)}ds
		\\\leq&\frac{1}{2}\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)-v_1(\varrho)\|^2)+8c_1^2\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
Combining \eqref{eq:3.11}-\eqref{eq:3.15}, we have that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.16}
	\begin{aligned}
		\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)\leq[(&\lambda+\delta^2-\alpha \delta)\wedge \frac{1}{2}]^{-1}[1+4\nu+4\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}\\&+4(1+2c_1^2)\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}]\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
Employing the Gronwall inequality, we see
\begin{equation}\label{eq:3.17}
	\begin{aligned}
		\mathbb{E}(\sup_{\tau \leq \varrho \leq T}\|\Phi(\varrho)-\Phi_1(\varrho)\|^2)=0
	\end{aligned}
\end{equation}
which implies the uniqueness.\par
\textbf{Step3:} Finally, we prove that $\mathcal{L}_{\Phi_{(t)}}\in\mathcal{P}^2(\ell^2\times\ell^2)$ for any $\tau\leq t\leq T$. Applying the $It\hat{o}$ formula and using \eqref{eq:2.17}-\eqref{eq:2.18}, we get that
\begin{equation*}
	\begin{aligned}
		\|u(t)\|^2=\|u_{\tau}\|^2+2\int_{\tau}^{t}(u(s),v(s))ds-2\delta \int_{\tau}^{t}\|u(s)\|^2ds,\\		
	\end{aligned}
\end{equation*}
and
\begin{equation*}
	\begin{aligned}		
		\|v(t)\|^2=&\|v_{\tau}\|^2-2(\lambda+\delta^2-\alpha \delta)\int_{\tau}^{t}(u(s),v(s))ds-2(\alpha-\delta)\int_{\tau}^{t}\|v(s)\|^2ds-2\nu \int_{\tau}^{t}(Au(s),v(s))ds\\&+2\int_{\tau}^{t}(v(s),g(s))ds+2\int_{\tau}^{t}(v(s),f(s,u(s),\mathcal{L}_{u(s)}))ds\\&+2\int_{\tau}^{t}(v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})dW(s))+\int_{\tau}^{t}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds.
	\end{aligned}
\end{equation*}
which implies that for any $\tau\leq t\leq T$,
\begin{equation}\label{eq:3.18}
	\begin{aligned}
		&\mathbb{E}(\sup_{\tau \leq \varrho \leq t}[(\lambda+\delta^2-\alpha \delta)\|u(\varrho)\|^2+\|v(\varrho)\|^2])\\\leq&\mathbb{E}[(\lambda+\delta^2-\alpha \delta)\|u_{\tau}\|^2+\|v_{\tau}\|^2]+2\nu\left|\int_{\tau}^{t}\mathbb{E}(Au(s),v(s))ds\right|\\&+2\int_{\tau}^{t}\mathbb{E}(v(s),g(s))ds+2\int_{\tau}^{t}\mathbb{E}(v(s),f(s,u(s),\mathcal{L}_{u(s)}))ds\\&+\int_{\tau}^{t}\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds+2\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}(v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})dW(s))\|).
	\end{aligned}
\end{equation}
 For the second term on the right-hand side of \eqref{eq:3.18}, by using \eqref{eq:2.9} and \eqref{eq:2.10} we have that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.19}
	\begin{aligned}
		2\nu\left|\int_{\tau}^{t}\mathbb{E}(Au(s),v(s))ds\right|\leq&\nu\int_{\tau}^{t}\mathbb{E}(\|Bu(s)\|^2+\|Bv(s)\|^2)ds\\\leq&4\nu\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds.
	\end{aligned}
\end{equation}
For the third term on the right-hand side of \eqref{eq:3.18}, by using Holder inequality and Young inequality, we find that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.20}
	\begin{aligned}
		2\int_{\tau}^{t}\mathbb{E}(v(s),g(s))ds\leq&\int_{\tau}^{t}\mathbb{E}\|v(s)\|^2ds+\int_{\tau}^{t}\mathbb{E}\|g(s)\|^2\\\leq&\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds+\int_{\tau}^{T}\mathbb{E}\|g(s)\|^2.
	\end{aligned}
\end{equation}
For the fourth term on the right-hand side of \eqref{eq:3.18}, by using \eqref{eq:2.13} and \eqref{eq:2.8}, we get that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.21}
	\begin{aligned}
		2\int_{\tau}^{t}\mathbb{E}(v(s),f(s,u(s),\mathcal{L}_{u(s)}))ds\leq&\int_{\tau}^{t}\mathbb{E}\|v(s)\|^2ds+\int_{\tau}^{t}\mathbb{E}\|f(s,u(s),\mathcal{L}_{u(s)})\|^2ds\\\leq&\int_{\tau}^{t}\mathbb{E}\|v(s)\|^2ds+\int_{\tau}^{t}\mathbb{E}(3\|\gamma(s)\|^2(1+\|u(s)\|^2+\mathbb{E}\|u(s)\|^2))ds+\\\leq&(1+6\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)})\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds+3(T-\tau)\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}.
	\end{aligned}
\end{equation}
For the fifth term on the right-hand side of \eqref{eq:3.18}, by using \eqref{eq:2.14} and \eqref{eq:2.8}, we know that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.22}
	\begin{aligned}
		\int_{\tau}^{t}\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds\leq&8\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds+2(T-\tau)\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}.
	\end{aligned}
\end{equation}
For the fourth term on the right-hand side of \eqref{eq:3.18}, by using the BDG inequality and \eqref{eq:3.22}, we get that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.23}
	\begin{aligned}
		&2\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\int_{\tau}^{\varrho}(v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})dW(s))\|)
		\\\leq&2c_1\mathbb{E}\{\int_{\tau}^{t}\|(v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)}))\|^2ds\}^{\frac{1}{2}}
		\\\leq&2c_1\mathbb{E}\{\int_{\tau}^{t}\|v(s)\|^2\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds\}^{\frac{1}{2}}
		\\\leq&2c_1\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)\|^2)^{\frac{1}{2}}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds)^{\frac{1}{2}}
		\\\leq&\frac{1}{2}\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)\|^2)+2c_1^2\mathbb{E}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|^2_{L_2(\ell^2,\ell^2)}ds
		\\\leq&\frac{1}{2}\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|v(\varrho)\|^2)+16c_1^2\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds+4c_1(T-\tau)\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}.
	\end{aligned}
\end{equation}
Together with \eqref{eq:3.18}-\eqref{eq:3.23}, we obtain that for all $ \tau \leq t \leq T $,
\begin{equation*}
	\begin{aligned}
		\mathbb{E}(\sup_{\tau \leq \varrho \leq t}\|\Phi(\varrho)\|^2)\leq&2\mathbb{E}\|\Phi_{\tau}\|^2\\&+(\lambda+\delta^2-\alpha \delta)^{-1}\{\int_{\tau}^{T}\mathbb{E}\|g(s)\|^2+[(T-\tau)[3\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+2(1+2c_1^2)\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}]]\}\\&+2[1+2\nu+3\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+8(1+2c_1^2)\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}]\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds\\:=&\triangle_1+\triangle_2\int_{\tau}^{t}(\sup_{\tau \leq \varrho \leq s}\|\Phi(\varrho)\|^2)ds,
	\end{aligned}
\end{equation*}
obviously, $\triangle_1$ and $\triangle_2$ are positive constants independent of t.\\
Applying the Gronwall inequality, we have that we obtain that for all $ \tau \leq t \leq T $,
\begin{equation}\label{eq:3.24}
	\begin{aligned}
		\mathbb{E}\|\Phi(t)\|^2)\leq\triangle_1e^{2\triangle_2(T-\tau)}<\infty.
	\end{aligned}
\end{equation}
Hence, $\mathcal{L}_{\Phi_{(t)}}\in\mathcal{P}^2(\ell^2\times\ell^2)$ for all $\tau\leq t\leq T$. This completes the proof.

\label{lem:4.1}
Suppose (A1)-(A3), \eqref{eq:2.21}--\eqref{eq:2.23} and \eqref{eq:2.25} hold. Then for every $\tau\in\mathbb{R}$ and $D_1=\{D_1(t):t\in\mathbb{R}\}\in\mathcal{D}_0$, there exists $T:=T(\tau,D_1)>0$, such that for all $t\geq T,\ \Phi_{\tau-t}=\binom{u_{\tau-t}}{v_{\tau-t}}\in L^2_{\mathcal{F}_{\tau-t}}(\Omega,\ell^2\times\ell^2)$ with $\mathcal{L}_{\Phi_{\tau-t}}\in D_1(\tau-t)$, the solution $\Phi=\binom{u}{v}$ of system \eqref{eq:2.16} satisfies
\begin{equation}
\begin{aligned}
	\label{eq:4.1}
	\mathbb{E}\left(\|u(\tau,\tau-t,u_{\tau-t})\|^2+\|v(\tau,\tau-t,v_{\tau-t})\|^2\right)\leq L_1+L_1\int_{-\infty}^{\tau}e^{\beta(s-\tau)}\|g(s)\|^2ds,
\end{aligned}
\end{equation}
where $L_1>0$ is a constant depending on $\beta,\ \alpha,\ \delta,\ \|\gamma\|_{L^\infty([\tau,T],\ell^2)}$ and $\|\chi\|_{L^\infty(\mathbb{R},\ell^2)}$, but independent of $\tau$ and $D_1$.

By \eqref{eq:2.16} and $It\hat{o}$ formula, we have for all $t\geq\tau$,
\begin{align*}
	d\|u(t)\|^2=2(u(t),v(t))dt-2\delta\|u(t)\|^2dt
\end{align*}
and
\begin{align*}
	d\|v(t)\|^2=&-2(\lambda+\delta^2-\alpha\delta)(u(t),v(t))dt-2(\alpha-\delta)\|v(t)\|^2dt-2\nu(Au(t),v(t))dt\\&+2(f(t,u(t),\mathcal{L}_{u(t)}),v(t))dt+2(g(t),v(t))dt\\&+\|\tilde{\sigma}(t, u(t),\mathcal{L}_{u(t)})\|_{L_2(\ell^2,\ell^2)}^2dt+2(\tilde{\sigma}(t, u(t),\mathcal{L}_{u(t)}),v(t)dW(t)).
\end{align*}
Therefore, we have
\begin{equation}
	\begin{aligned}
	\label{eq:4.2}
	&\dfrac{d}{dt}\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|u(t)\|^2+\|v(t)\|^2+\nu\|Bu(t)\|^2\right)\\&+2\delta(\lambda+\delta^2-\alpha\delta)\mathbb{E}(\|u(t)\|^2)+2(\alpha-\delta)\mathbb{E}(\|v(t)\|^2)+2\nu\delta\mathbb{E}(\|Bu(t)\|^2)\\=&2\mathbb{E}(f(t,u(t),\mathcal{L}_{u(t)}),v(t))+2\mathbb{E}(g(t),v(t))+\mathbb{E}\left(\|\tilde{\sigma}(t, u(t),\mathcal{L}_{u(t)})\|_{L_2(\ell^2,\ell^2)}^2\right).
\end{aligned}
\end{equation}
By  \eqref{eq:2.13}, \eqref{eq:2.8} and Young's inequality, we obtain
\begin{equation}
	\begin{aligned}
		\label{eq:4.3}
	2\mathbb{E}(f(t,u(t),\mathcal{L}_{u(t)}),v(t))&\leq \dfrac{2}{(\alpha-\delta)}\mathbb{E}\|f(t,u(t),\mathcal{L}_{u(t)}\|^2+\dfrac{(\alpha-\delta)}{2}\mathbb{E}\|v(t)\|^2
	 \\&\leq\dfrac{6}{(\alpha-\delta)}\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+\dfrac{12}{(\alpha-\delta)}\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}\mathbb{E}\|u(t)\|^2+\dfrac{(\alpha-\delta)}{2}\mathbb{E}\|v(t)\|^2.
	\end{aligned}
\end{equation}
and
\begin{align}
	\label{eq:4.4}
2\mathbb{E}(g(t),v(t))\leq\dfrac{2}{(\alpha-\delta)}\mathbb{E}\|g(t)\|^2+\dfrac{2}{(\alpha-\delta)}\mathbb{E}\|v(t)\|^2.
\end{align}
For the last term on the right-hand side of \eqref{eq:4.2}, we infer from \eqref{eq:2.14} and \eqref{eq:2.8} that
\begin{equation}
	\begin{aligned}
		\label{eq:4.5}
		\mathbb{E}\left(\|\tilde{\sigma}(t, u(t),\mathcal{L}_{u(t)})\|_{L_2(\ell^2,\ell^2)}^2\right)\leq 8\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\mathbb{E}\|u(t)\|^2+2\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}.
	\end{aligned}
\end{equation}
Substituting \eqref{eq:4.3}--\eqref{eq:4.5} into \eqref{eq:4.2}, by \eqref{eq:2.21}--\eqref{eq:2.23}, we have
\begin{equation}
	\begin{aligned}
		\label{eq:4.6}
		&\dfrac{d}{dt}\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|u(t)\|^2+\|v(t)\|^2+\nu\|Bu(t)\|^2\right]\\&+\beta\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|u(t)\|^2+\|v(t)\|^2+\nu\|Bu(t)\|^2\right]\\\leq&\dfrac{2}{(\alpha-\delta)}(3\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+\|g(t)\|^2)+2\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}.
	\end{aligned}
\end{equation}
Multiplying \eqref{eq:4.6} by $e^{\beta t}$ and integrating over $(\tau-t,\tau)$ with $t\in\mathbb{R}^+$, we see 
\begin{equation}
	\begin{aligned}
		\label{eq:4.7}
	\mathbb{E}&\left[(\lambda+\delta^2-\alpha\delta)\|u(\tau,\tau-t,u_{\tau-t})\|^2+\|v(\tau,\tau-t,v_{\tau-t})\|^2+\nu\|Bu(\tau,\tau-t,u_{\tau-t})\|^2\right]
	\\&\leq e^{-\beta t}\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|u_{\tau-t}\|^2+\|v_{\tau-t}\|^2+\nu\|Bu_{\tau-t}\|^2\right]
	\\&+\dfrac{2}{(\alpha-\delta)}\int_{\tau-t}^{\tau}e^{\beta(s-\tau)}\|g(s)\|^2ds+\frac{1}{\beta}(\dfrac{6}{(\alpha-\delta)}\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+2\|\chi\|^2_{L^\infty(\mathbb{R},\ell^2)}).
	\end{aligned}
\end{equation}
Since $\mathcal{L}_{\Phi_{\tau-t}}\in D_1(\tau-t)$ with $D_1\in\mathcal{D}_0$, we get
\begin{equation*}
	\begin{aligned}
		&\lim_{t \to\infty}e^{-\beta t}\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|u_{\tau-t}\|^2+\|v_{\tau-t}\|^2+\nu\|Bu_{\tau-t}\|^2\right)\\ &\leq(\lambda+\delta^2-\alpha\delta+4\nu+1)e^{-\beta\tau}\lim_{t \to\infty}e^{\beta(\tau-t)}\|D_1(\tau-t)\|_{\mathcal{P}_2(\ell^2\times\ell^2)}^2=0.
	\end{aligned}
\end{equation*}
Hence, there exists $T=T(\tau,D_1)$ such that for all $t\geq T$,
\begin{equation*}
	\begin{aligned}
		e^{-\beta t}\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|u_{\tau-t}\|^2+\|v_{\tau-t}\|^2+\nu\|Bu_{\tau-t}\|^2\right)\leq\frac{1}{\beta},
	\end{aligned}
\end{equation*}
This along with \eqref{eq:4.7} and \eqref{eq:2.25} concludes the proof.

\label{lem:4.2}
	Suppose (A1)-(A3), \eqref{eq:2.21}--\eqref{eq:2.23} and \eqref{eq:2.25} hold. Then the solution $\Phi(\tau,\tau-t,\Phi_{\tau-t})=\binom{u(\tau,\tau-t,u_{\tau-t})}{v(\tau,\tau-t,v_{\tau-t})}$ of system \eqref{eq:2.16} with initial time $\tau-t$ satisfies
	\begin{equation}
		\begin{aligned}
			\label{eq:4.8}
			\sup_{t\geq0}\mathbb{E}\left(\|u(\tau,\tau-t,u_{\tau-t})\|^2+\|v(\tau,\tau-t,v_{\tau-t})\|^2\right)\leq L_2\mathbb{E}(\|u_{\tau-t}\|^2+\|v_{\tau-t}\|^2)+L_2(1+\|g\|^2),
		\end{aligned}
	\end{equation}
	where $\Phi_{\tau-t}=\binom{u_{\tau-t}}{v_{\tau-t}}\in L^2(\Omega,\mathcal{F}_{\tau-t},\ell^2\times\ell^2)$ and $L_2>0$ is a constant depending on $\lambda,\ \beta,\ \alpha,\ \|\gamma\|_{L^\infty([\tau,T],\ell^2)}$ and $\|\chi\|_{L^\infty(\mathbb{R},\ell^2)}$, but independent of $t$ and $\Phi_{\tau-t}$.

\label{lem:4.3}
	Suppose (A1)-(A3), \eqref{eq:2.21}--\eqref{eq:2.23} and \eqref{eq:2.25} hold. Then for every $\varepsilon>0,\ \tau\in\mathbb{R}$ and $D_1=\{D_1(t):t\in\mathbb{R}\}\in\mathcal{D}_0$, there exists $T=T(\varepsilon,\tau,D_1)$ and $N=N(\varepsilon,\tau)\in\mathbb{N}^+$, such that for all $ t\geq \tau$, $n\geq\mathbb{N}$ and $\Phi_{\tau-t}=\binom{u_{\tau-t}}{v_{\tau-t}}\in L^2_{\mathcal{F}_{\tau-t}}(\Omega,\ell^2\times\ell^2)$ with $\mathcal{L}_{\Phi_{\tau-t}}\in D_1(\tau-t)$,  the solution $\Phi=\binom{u}{v}$ of system \eqref{eq:2.16} satisfies
\begin{align*}
	\mathbb{E}\left(\sum_{\left|i\right|\geq n}(\left|u_i(\tau,\tau-t,u_{\tau-t})\right|^2+\left|v_i(\tau,\tau-t,v_{\tau-t})\right|^2)\right)\leq\varepsilon.
\end{align*}

For each $n\in\mathbb{N}$, we denote $\rho_n=\left(\rho\left(\frac{\left|i\right|}{n}\right)\right)_{i\in\mathbb{Z}}$, $\rho_nu=\left(\rho\left(\frac{\left|i\right|}{n}\right)u_i\right)_{i\in\mathbb{Z}}$, and $\rho_nv=\left(\rho\left(\frac{\left|i\right|}{n}\right)v_i\right)_{i\in\mathbb{Z}}$.By \eqref{eq:2.16}, we get
\begin{align}
	\label{eq:4.9}
	d\rho_n\Phi(t)=\rho_n F(\Phi(t))dt+\rho_nG(\Phi(t))dW(t),
\end{align}	
	which along with $It\hat{o}$ formula implies that
\begin{align*}
	e^{\beta t}\|\rho_nu(t)\|^2=e^{\beta \tau}\|\rho_nu_{\tau}\|^2+(\beta-2\delta)\int_{\tau}^{t}e^{\beta s}\|\rho_nu(s)\|^2ds+2\int_{\tau}^{t}e^{\beta s}(\rho_n^2u(s),v(s))ds
\end{align*}
and
\begin{align*}
	&e^{\beta t}\|\rho_nv(t)\|^2+2(\lambda+\delta^2-\alpha\delta)\int_{\tau}^{t}e^{\beta s}(u(s),\rho_n^2v(s))ds+2(\alpha-\delta)\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds\\&+2\nu\int_{\tau}^{t}e^{\beta s}(Au(s),\rho_n^2v(s))ds\\=&e^{\beta \tau}\|\rho_nv_{\tau}\|^2+2\int_{\tau}^{t}e^{\beta s}(f(s,u(s),\mathcal{L}_{u(s)}),\rho_n^2v(s))ds+2\int_{\tau}^{t}e^{\beta s}(g(s),\rho_n^2v(s))ds\\&+\int_{\tau}^{t}e^{\beta s}\|\rho_n\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds+2\int_{\tau}^{t}e^{\beta s}(\rho_n^2v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})dW(s))
\end{align*}
Thus, we have
\begin{equation}
	\begin{aligned}
		\label{eq:4.10}
		&\mathbb{E}\left[e^{\beta t}((\lambda+\delta^2-\alpha\delta)\|\rho_nu(t)\|^2+\|\rho_nv(t)\|^2)\right]+(2\delta-\beta)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\lambda+\delta^2-\alpha\delta)\|\rho_nu(s)\|^2ds)\\&+(2(\alpha-\delta)-\beta)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds)
		\\=&\mathbb{E}\left[e^{\beta \tau}((\lambda+\delta^2-\alpha\delta)\|\rho_nu_{\tau}\|^2+\|\rho_nv_{\tau}\|^2)\right]-2\nu\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(Au(s),\rho_n^2\dot{u}(s))ds)\\&-2\nu\delta\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(Au(s),\rho_n^2u(s))ds)+2\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(f(s,u(s),\mathcal{L}_{u(s)}),\rho_n^2v(s))ds)\\&+2\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(g(s),\rho_n^2v(s))ds)+\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_n\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds).
	\end{aligned}
\end{equation}	
In the view of the following fact that
\begin{equation}
	\begin{aligned}
		\label{eq:4.11}
	(Au(s),\rho_n^2\dot{u}(s))=&(Bu(s),B(\rho_n^2\dot{u}(s)))\\=&\sum_{i\in\mathbb{Z}}(u_{i+1}(s)-u_i(s))\left(\rho^2\left(\frac{i+1}{n}\right)\dot{u}_(i+1)(s)-\rho^2\left(\frac{i}{n}\right)\dot{u}_i(s)\right)\\=&\sum_{i\in\mathbb{Z}}\rho^2\left(\frac{i}{n}\right)(u_{i+1}(s)-u_i(s))(\dot{u}_{i+1}(s)-\dot{u}_i(s))\\&+\sum_{i\in\mathbb{Z}}(\rho^2\left(\frac{i+1}{n}\right)-\rho^2\left(\frac{i}{n}\right))(u_{i+1}(s)-u_i(s))\dot{u}_{i+1}(s),
	\end{aligned}
\end{equation}	
then, the last term on the right-hand side of \eqref{eq:4.11} satisfies
\begin{equation}
	\begin{aligned}
		\label{eq:4.12}
	&\sum_{i\in\mathbb{Z}}(\rho^2\left(\frac{i+1}{n}\right)-\rho^2\left(\frac{i}{n}\right))(u_{i+1}(s)-u_i(s))\dot{u}_{i+1}(s)\\\leq&2n^{-1}c_0\sum_{i\in\mathbb{Z}}\left|u_{i+1}(s)-u_i(s)\right|\left|\dot{u}_{i+1}(s)\right|\\\leq&2n^{-1}c_0\sum_{i\in\mathbb{Z}}(\left|u_i(s)\right|^2+\left|\dot{u}_{i+1}(s)\right|^2)\\\leq&2n^{-1}c_0(\|u(s)\|^2+\|v(s)-\delta u(s)\|^2)\\\leq&2n^{-1}c_0(2\delta^2+3)(\|u(s)\|^2+\|v(s)\|^2),
	\end{aligned}
\end{equation}
where $c_0$ is a constant such that $\left|\rho'(s)\right|\leq c_0$ for all $s\in\mathbb{R}$.		
Then, it follows from \eqref{eq:4.11} and \eqref{eq:4.12} that
\begin{equation}
	\begin{aligned}
		\label{eq:4.13}
		(Au(s),\rho_n^2\dot{u}(s))\geq\frac{1}{2}\dfrac{d}{ds}\|\rho_nBu(s)\|^2-2n^{-1}c_0(2\delta^2+3)(\|u(s)\|^2+\|v(s)\|^2).
	\end{aligned}
\end{equation}
Therefore, the second term on the right-hand side of \eqref{eq:4.10} satisfies
\begin{equation}
	\begin{aligned}
		\label{eq:4.14}
	-2\nu\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(Au(s),\rho_n^2\dot{u}(s))ds)\leq& -2\nu\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\frac{1}{2}d\|\rho_nBu(s)\|^2)\\&+4\nu n^{-1}c_0(2\delta^2+3)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\|u(s)\|^2+\|v(s)\|^2)ds)\\\leq&-\nu\mathbb{E}(e^{\beta t}\|\rho_nBu(t)\|^2-e^{\beta\tau}\|\rho_nBu_{\tau}\|^2)+\nu\beta\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nBu(s)\|^2ds)\\&+4\nu n^{-1}c_0(2\delta^2+3)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\|u(s)\|^2+\|v(s)\|^2)ds).
	\end{aligned}
\end{equation}	
Similarly to \eqref{eq:4.11}, we obtain
\begin{equation}
	\begin{aligned}
		\label{eq:4.15}
		(Au(s),\rho_n^2u(s))=&(Bu(s),B(\rho_n^2u(s)))=\sum_{i\in\mathbb{Z}}(u_{i+1}(s)-u_i(s))(\rho^2\left(\frac{i+1}{n}\right)u_{i+1}(s)-\rho^2\left(\frac{i}{n}\right)u_i(s))\\=&\sum_{i\in\mathbb{Z}}\rho^2\left(\frac{i}{n}\right)(u_{i+1}(s)-u_i(s))^2+\sum_{i\in\mathbb{Z}}(\rho^2\left(\frac{i+1}{n}\right)-\rho^2\left(\frac{i}{n}\right))(u_{i+1}(s)-u_i(s))u_{i+1}(s).
	\end{aligned}
\end{equation}	
Note that the last term on the right-hand side of \eqref{eq:4.15} is bounded by
	\begin{equation}
		\begin{aligned}
			\label{eq:4.16}
			\sum_{i\in\mathbb{Z}}(\rho^2\left(\frac{i+1}{n}\right)-\rho^2\left(\frac{i}{n}\right))(u_{i+1}(s)-u_i(s))u_{i+1}(s)\leq4n^{-1}c_0\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|u(s)\|^2ds).
		\end{aligned}
	\end{equation}
It yields from  \eqref{eq:4.15} and \eqref{eq:4.16} that the third term on the right-hand side of \eqref{eq:4.10} satisfies
\begin{equation}
	\begin{aligned}
		\label{eq:4.17}
	-2\nu\delta\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(Au(s),\rho_n^2u(s))ds)\leq-2\nu\delta\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nBu(s)\|^2ds)+8\nu\delta n^{-1}c_0\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|u(s)\|^2ds).
	\end{aligned}
\end{equation}
By \eqref{eq:2.4}, the forth term on the right-hand side of \eqref{eq:4.10} satisfies
\begin{equation}
	\begin{aligned}
		\label{eq:4.18}
		&2\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(f(s,u(s),\mathcal{L}_{u(s)}),\rho_n^2v(s))ds)\\\leq&\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\dfrac{2}{\alpha-\delta}\|\rho_nf(s,u(s),\mathcal{L}_{u(s)})\|^2+\dfrac{\alpha-\delta}{2}\|\rho_nv(s)\|^2)ds)\\\leq&\dfrac{6}{\alpha-\delta}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\sum_{i\in\mathbb{Z}}\rho^2\left(\frac{i}{n}\right)\gamma_i(s)(1+\left|u_i(s)\right|^2+\mathbb{E}\left|u_i(s)\right|^2)ds)+\dfrac{\alpha-\delta}{2}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds)\\\leq&\dfrac{6}{\alpha-\delta}\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|\gamma_i(s)\right|ds+\dfrac{12}{\alpha-\delta}\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nu(s)\|^2ds)+\dfrac{\alpha-\delta}{2}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds).
	\end{aligned}
\end{equation}
For the forth term on the right-hand side of \eqref{eq:4.10}, we have
\begin{align}
	\label{eq:4.19}
	2\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(g(s),\rho_n^2v(s))ds)\leq\frac{2}{\alpha-\delta}\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|g_i(s)\right|^2ds+\frac{\alpha-\delta}{2}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds).
\end{align}
By \eqref{eq:2.7}, we see that for any $u = (u_i)_{i \in \mathbb{Z}} \in \ell^2$ and $\mu = (\mu_i)_{i \in \mathbb{Z}} \in \mathcal{L}^2$,
\begin{align*}
\|\rho_n\tilde{\sigma}(s, u(s),\mu)\|_{L_2(\ell^2,\ell^2)}^2\leq 4\|\kappa(s)\|^2(\|\rho_nu(s)\|^2+\sum_{i\in\mathbb{Z}}\rho^2\left(\frac{i}{n}\right)\mathbb{W}_2^{\mathbb{R}}(\mu, \delta_0)^2)+2\|\rho_n\chi(s)\|^2,
\end{align*}
which implies that
\begin{equation}
	\begin{aligned}
		\label{eq:4.20}
		&\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_n\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds)\\\leq&8\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nu(s)\|^2ds)+2\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|\chi_i(s)\right|ds.
	\end{aligned}
\end{equation}
By \eqref{eq:4.14},\eqref{eq:4.17}--\eqref{eq:4.20}, we find from \eqref{eq:4.10} that
\begin{equation}
	\begin{aligned}
		\label{eq:4.21}
		&\mathbb{E}\left[e^{\beta t}((\lambda+\delta^2-\alpha\delta)\|\rho_nu(t)\|^2+\|\rho_nv(t)\|^2)+\nu\|\rho_nBu(t)\|^2\right]\\&+(2\delta-\beta)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\lambda+\delta^2-\alpha\delta)\|\rho_nu(s)\|^2ds)\\&+[(\alpha-\delta)-\beta]\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nv(s)\|^2ds)+
		(2\delta-\beta)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\nu\|\rho_nBu(s)\|^2ds)\\\leq&\mathbb{E}\left[e^{\beta \tau}((\lambda+\delta^2-\alpha\delta)\|\rho_nu_{\tau}\|^2+\|\rho_nv_{\tau}\|^2)+\nu\|\rho_nBu_{\tau}\|^2\right]\\&+4\nu n^{-1}c_0(2\delta^2+2\delta+3)\mathbb{E}(\int_{\tau}^{t}e^{\beta s}(\|u(s)\|^2+\|v(s)\|^2)ds)\\&+(\dfrac{12}{\alpha-\delta}\|\gamma\|^2_{L^\infty([\tau,T],\ell^2)}+8\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)})\mathbb{E}(\int_{\tau}^{t}e^{\beta s}\|\rho_nu(s)\|^2ds)\\&+\dfrac{6}{\alpha-\delta}\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|\gamma_i(s)\right|ds+\frac{2}{\alpha-\delta}\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|g_i(s)\right|^2ds+2\int_{\tau}^{t}e^{\beta s}\sum_{\left|i\right|\geq n}\left|\chi_i(s)\right|ds.
	\end{aligned}
\end{equation}	
Following \eqref{eq:2.23}, then replacing where $\tau$ and $t$ by $\tau-t$ and $\tau$, respectively, we obtain
	\begin{equation}
		\begin{aligned}
			\label{eq:4.22}
			&\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|\rho_nu(\tau,\tau-t,u_{\tau-t})\|^2+\|\rho_nv(\tau,\tau-t,v_{\tau-t})\|^2+\nu\|\rho_nBu(\tau,\tau-t,u_{\tau-t})\|^2\right]\\\leq&\mathbb{E}\left[e^{-\beta t}((\lambda+\delta^2-\alpha\delta)\|\rho_nu_{\tau-t}\|^2+\|\rho_nv_{\tau-t}\|^2+\nu\|\rho_nBu_{\tau-t}\|^2)\right]\\&+4\nu n^{-1}c_0(2\delta^2+2\delta+3)\mathbb{E}(\int_{-\infty}^{\tau}e^{\beta( s-\tau)}(\|u(s)\|^2+\|v(s)\|^2)ds)\\&+\frac{2}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|g_i(s)\right|^2ds+\dfrac{6}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\gamma_i(s)\right|ds+2\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\chi_i(s)\right|ds.
		\end{aligned}
	\end{equation}
For the first term on the right-hand side of \eqref{eq:4.22}, since $\mathcal{L}_{\Phi_{\tau-t}}\in D_1(\tau-t)$, we get that
	\begin{align*}
		&e^{-\beta\tau} e^{\beta(\tau-t)}\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|u_{\tau-t}\|^2+\|nv_{\tau-t}\|^2+\nu\|Bu_{\tau-t}\|^2\right]\\\leq& (\lambda+\delta^2-\alpha\delta+1+4
		\nu)e^{-\beta\tau}e^{\beta(\tau-t)}\mathbb{E}\|D_1(\tau-t)\|_{\mathcal{P}_2(\ell^2\times\ell^2)}^2\\&\rightarrow0,
	\end{align*}
as $t\rightarrow\infty$. Hence for $\varepsilon>0$, there exists $T_2=T_2(\varepsilon,\tau,D_1)\geq T_1$ such that for all $t\geq T_2$,
	\begin{align*}
		&e^{-\beta t}\mathbb{E}\left[(\lambda+\delta^2-\alpha\delta)\|\rho_nu_{\tau-t}\|^2+\|\rho_nv_{\tau-t}\|^2+\nu\|\rho_nBu_{\tau-t}\|^2\right]\\\leq& \frac{\varepsilon}{4}.
	\end{align*}
	Moreover, it follows from Lemma \ref{lem:4.2} that there exists a costant $C_2>0$ indepensent of $n$ such that for all $t\geq \tau$,
\begin{equation*}
	\begin{aligned}
		&4\nu n^{-1}c_0(2\delta^2+2\delta+3)\mathbb{E}(\int_{-\infty}^{\tau}e^{\beta( s-\tau)}(\|u(s)\|^2+\|v(s)\|^2)ds)\\\leq&4\nu (\beta n)^{-1}c_0(2\delta^2+2\delta+3)\sup_{t\geq0}\mathbb{E}((\|u(\tau,\tau-t,u_{\tau-t})\|^2+\|v(\tau,\tau-t,v_{\tau-t})\|^2)ds) \\\leq& \frac{C_2}{n}\rightarrow0\text{\ \ as\ \ }n\rightarrow\infty.
\end{aligned}
\end{equation*}
Therefore,  there exists $N_1=N_1(\varepsilon,\tau)\in\mathbb{N}^+$ such that for all $n\geq N_1$,
\begin{equation*}
	\begin{aligned}
		4\nu n^{-1}c_0(2\delta^2+2\delta+3)\mathbb{E}(\int_{-\infty}^{\tau}e^{\beta( s-\tau)}(\|u(s)\|^2+\|v(s)\|^2)ds)\leq\frac{\varepsilon}{4}.
	\end{aligned}
\end{equation*}
For the fourth term on the right-hand side of \eqref{eq:4.22}, by using \eqref{eq:2.25}, we notice that
\begin{equation*}
	\begin{aligned}
		\frac{2}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|g_i(s)\right|^2ds\leq\frac{2}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\|g(s)\|^2ds<\infty.
	\end{aligned}
\end{equation*}
By the dominated convergence theorem, there exists $N_2=N_2(\varepsilon,\tau)\geq N_1$ such that for all $n\geq N_2$,
\begin{equation*}
	\begin{aligned}
		\frac{2}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|g_i(s)\right|^2ds\leq\frac{\varepsilon}{4}.
	\end{aligned}
\end{equation*}
For the last two terms on the right-hand side of \eqref{eq:4.22}, using the fact that $\gamma\in L^\infty_{loc}(\mathbb{R}, \ell^2)$ and $\chi\in L^\infty(\mathbb{R}, \ell^2)$, we know that
\begin{equation*}
	\begin{aligned}
	&\dfrac{6}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\gamma_i(s)\right|ds+2\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\chi_i(s)\right|ds\\\leq&(\dfrac{6}{\alpha-\delta}+2)\int_{-\infty}^{\tau}e^{\beta (s-\tau)}(\left|\gamma(s)\right|^2+\left|\chi(s)\right|^2)ds\\\leq&(\dfrac{6}{\alpha-\delta}+2)\beta^{-1}(\|\gamma\|_{L^\infty_{loc}(\mathbb{R}, \ell^2)}^2+\|\chi\|_{L^\infty(\mathbb{R}, \ell^2)}^2).
	\end{aligned}
\end{equation*}
By the dominated convergence theorem again, there exists $N_3=N_3(\varepsilon,\tau)\geq N_2$ such that for all $n\geq N_3$,
\begin{equation*}
	\begin{aligned}
		\dfrac{6}{\alpha-\delta}\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\gamma_i(s)\right|ds+2\int_{-\infty}^{\tau}e^{\beta (s-\tau)}\sum_{\left|i\right|\geq n}\left|\chi_i(s)\right|ds\leq\frac{\varepsilon}{4}.
	\end{aligned}
\end{equation*}
Combining all above, we have for all $t\geq T_2$ and $n\geq N_3$ that
\begin{align*}
	\mathbb{E}\left(\sum_{\left|i\right|\geq n}(\left|u_i(\tau,\tau-t,u_{\tau-t})\right|^2+\left|v_i(\tau,\tau-t,v_{\tau-t})\right|^2)\right)<\varepsilon,
\end{align*}
as desired.

\label{lem:4.4}
	Suppose (A1)-(A3), \eqref{eq:2.21}--\eqref{eq:2.26} hold. Then for every $ \tau\in\mathbb{R}$ and $D_2=\{D_2(t):t\in\mathbb{R}\}\in\mathcal{D}$, there exists $T:=T(\tau,D_2)>0$, such that for all $ t>T$, $\Phi_{\tau-t}=\binom{u_{\tau-t}}{v_{\tau-t}}\in L^2_{\mathcal{F}_{\tau-t}}(\Omega,\ell^2\times\ell^2)$ with $\mathcal{L}_{\Phi_{\tau-t}}\in D_2(\tau-t)$,  the solution $\Phi=\binom{u}{v}$ of system \eqref{eq:2.16} satisfies
\begin{equation}
	\begin{aligned}
		\label{eq:4.23}
		\mathbb{E}\left(\|u(\tau,\tau-t,u_{\tau-t})\|^4+\|v(\tau,\tau-t,v_{\tau-t})\|^4\right)\leq L_3+L_3\int_{-\infty}^{\tau}e^{2\beta(s-\tau)}\|g(s)\|^4ds,
	\end{aligned}
\end{equation}
where $L_3>0$ is a constant depending on $\beta,\ \alpha,\ \delta,\ \|\gamma\|_{L^\infty([\tau,T],\ell^2)}$ and $\|\chi\|_{L^\infty(\mathbb{R},\ell^2)}$, but independent of $\tau$ and $D_2$.

Let $\Phi(t)=\binom{u(t)}{v(t)}=\binom{u(\tau,\tau-t,u_{\tau-t})}{v(\tau,\tau-t,v_{\tau-t})}$ be the solution of \eqref{eq:2.16} with initial data $\Phi_{\tau-t}=\binom{u_{\tau-t}}{v_{\tau-t}}$ at initial time $\tau-t.$\par
By \eqref{eq:4.2} and $It\hat{o}$ formula, we have for all $t\geq\tau$,
\begin{align*}
	e^{2\beta t}\|u(t)\|^4=e^{2\beta\tau}\|u_{\tau}\|^4+2(\beta-2\delta)\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds+4\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^2(u(s),v(s))ds,
\end{align*}
and
\begin{align*}
	e^{2\beta t}\|v(t)\|^4=&e^{2\beta\tau}\|v_{\tau}\|^4+4\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(v(s),\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})dW(s))\\&+2[\beta-2(\alpha-\delta)]\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds
	-4(\lambda+\delta^2-\alpha\delta)\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(u(s),v(s))ds\\&-4\nu\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(Au(s),v(s))ds+4\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(f(s,u(s),\mathcal{L}_{u(s)}),v(s))ds\\&+4\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(g(s),v(s))ds+6\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds.
\end{align*}
Therefore, we have
\begin{equation}
	\begin{aligned}
		\label{eq:4.24}
		&\mathbb{E}\left(e^{2\beta t}(\|u(t)\|^4+\|v(t)\|^4)\right)+\mathbb{E}\left(2(2\delta-\beta)\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds+2(2(\alpha-\delta)-\beta)\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)\\=&\mathbb{E}\left(e^{2\beta\tau}(\|u_{\tau}\|^4+\|v_{\tau}\|^4)\right)+4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^2(u(s),v(s))ds\right)\\&-4(\lambda+\delta^2-\alpha\delta)\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(u(s),v(s))ds\right)-4\nu\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(Au(s),v(s))ds\right)\\&+4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(f(s,u(s),\mathcal{L}_{u(s)}),v(s))ds\right)+4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(g(s),v(s))ds\right)\\&+6\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds\right).
	\end{aligned}
\end{equation}
Then, we estimate each terms on the right-hand side of \eqref{eq:4.24} separately. For the second term, third term and sixth term, by H$\ddot{o}$lder and Young's inequality, we obtain,
\begin{equation}
	\begin{aligned}
		\label{eq:4.25}
		4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^2(u(s),v(s))ds\right)&\leq4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^3\|v(s)\|ds\right)
		\\&\leq\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+3\varepsilon_1\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds\right),
	\end{aligned}
\end{equation}
\begin{equation}
	\begin{aligned}
		\label{eq:4.26}
		&\left|-4(\lambda+\delta^2-\alpha\delta)\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(u(s),v(s))ds\right)\right|\\\leq&4(\lambda+\delta^2-\alpha\delta)\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|\|v(s)\|^3ds\right)
		\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\varepsilon_2(\lambda+\delta^2-\alpha\delta)^4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds\right),
	\end{aligned}
\end{equation}
and
\begin{align}
	\label{eq:4.27}
	4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(g(s),v(s))ds\right)\leq\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|g(s)\|^4ds\right),
\end{align}
where $\varepsilon^3_1=\dfrac{3}{(\alpha-\delta)}$, $\varepsilon_2=\left(\dfrac{9}{(\alpha-\delta)}\right)^3$ are positive constants.\par
For the fourth term	on the right-hand side of \eqref{eq:4.24}, by \eqref{eq:2.10}, we see,
\begin{equation}
	\begin{aligned}
		\label{eq:4.28}
		&\left|-4\nu\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(Au(s),v(s))ds\right)\right|\\\leq&16\nu\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|\|v(s)\|^3ds\right)
		\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+256\varepsilon_2\nu^4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds\right).
	\end{aligned}
\end{equation}	
For the fifth term	on the right-hand side of \eqref{eq:4.24}, by \eqref{eq:2.13} and \eqref{eq:2.8}, we get,
\begin{equation}
	\begin{aligned}
		\label{eq:4.29}
		&4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2(f(s,u(s),\mathcal{L}_{u(s)}),v(s))ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|f(s,u(s),\mathcal{L}_{u(s)})\|^4ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}[9\|\gamma(s)\|^4(3+3\|u(s)\|^4+3(\mathbb{E}\|u(s)\|^2)^2)]ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+27\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|\gamma(s)\|^4(1+2\|u(s)\|^4)ds\right).
	\end{aligned}
\end{equation}	
For the last term	on the right-hand side of \eqref{eq:4.24}, by \eqref{eq:2.14} and \eqref{eq:2.8}, we know,
\begin{equation}
	\begin{aligned}
		\label{eq:4.30}
		&6\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^2\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\dfrac{9}{2\varepsilon_3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|\tilde{\sigma}(s, u(s),\mathcal{L}_{u(s)})\|_{L_2(\ell^2,\ell^2)}^4ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\dfrac{9}{2\varepsilon_3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}[32\|\kappa(s)\|^4(2\|u(s)\|^4+2(\mathbb{E}\|u(s)\|^2)^2)+8\|\chi(s)\|^2]ds\right)\\\leq&\dfrac{(\alpha-\delta)}{3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+\dfrac{576}{\varepsilon_3}\|\kappa\|_{L^\infty(\mathbb{R}, \ell^2)}^4\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds\right)+\dfrac{36}{\varepsilon_3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|\chi(s)\|^4ds\right),
	\end{aligned}
\end{equation}	
where $\varepsilon_3=\dfrac{(\alpha-\delta)}{3}$.\par 
It follows from \eqref{eq:4.24}--\eqref{eq:4.30} that for all $t\geq \tau$,
\begin{equation}
	\begin{aligned}
		\label{eq:4.31}
		&\mathbb{E}\left(e^{2\beta t}(\|u(t)\|^4+\|v(t)\|^4)\right)+\mathbb{E}\left(2(2\delta-\beta)\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds+2(2(\alpha-\delta)-\beta)\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)\\\leq&\mathbb{E}\left(e^{2\beta\tau}(\|u_{\tau}\|^4+\|v_{\tau}\|^4)\right)\\&+\{3\varepsilon_1+\varepsilon_2[(\lambda+\delta^2-\alpha\delta)^4+256\nu^4+54\|\gamma\|^4_{L^\infty([\tau,T],\ell^2)}]+\dfrac{576}{\varepsilon_3}\|\kappa\|_{L^\infty(\mathbb{R}, \ell^2)}^4\}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|u(s)\|^4ds\right)\\&+2(\alpha-\delta)\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|v(s)\|^4ds\right)+27\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|\gamma(s)\|^4ds\right)\\&+\varepsilon_2\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|g(s)\|^4ds\right)+\dfrac{36}{\varepsilon_3}\mathbb{E}\left(\int_{\tau}^{t}e^{2\beta s}\|\chi(s)\|^4ds\right).
	\end{aligned}
\end{equation}
Replacing $\tau$ and $t$ in \eqref{eq:4.31} by $\tau-t$ and $\tau$, respectively, by \eqref{eq:2.24} we have for all $t\geq \tau$,
\begin{equation}
	\begin{aligned}
		\label{eq:4.32}
		\mathbb{E}\left(\|u(\tau,\tau-t,u_{\tau-t})\|^4+\|v(\tau,\tau-t,v_{\tau-t})\|^4\right)\leq&\mathbb{E}\left(e^{-2\beta t}(\|u_{\tau-t}\|^4+\|v_{\tau-t}\|^4)\right)\\&+27\varepsilon_2{(2\beta)}^{-1}\|\gamma\|^4_{L^\infty([\tau,T],\ell^2)}+18{(\varepsilon_3\beta)}^{-1}\|\chi\|_{L^\infty(\mathbb{R}, \ell^2)}^4\\&+\varepsilon_2\mathbb{E}\left(\int_{\tau-t}^{\tau}e^{2\beta(s-\tau)}\|g(s)\|^4ds\right).
	\end{aligned}
\end{equation}
Note that $\mathcal{L}_{\Phi_{\tau-t}}\in D_2(\tau-t)$ with $D_2\in\mathcal{D}$, we get
\begin{equation*}
	\begin{aligned}
		\lim_{t \to\infty}e^{-2\beta t}\mathbb{E}\left(\|u_{\tau-t}\|^4+\|v_{\tau-t}\|^4\right)\leq e^{-2\beta\tau}\lim_{t \to\infty}e^{2\beta(\tau-t)}\|D_2(\tau-t)\|_{\mathcal{P}_4(\ell^2\times\ell^2)}^2=0.
	\end{aligned}
\end{equation*}
Hence, there exists $T=T(\tau,D_2)$ such that for all $t\geq T$,
\begin{equation*}
	\begin{aligned}
		e^{-2\beta t}\mathbb{E}\left(\|u_{\tau-t}\|^4+\|v_{\tau-t}\|^4\right)\leq1,
	\end{aligned}
\end{equation*}
Then we can obtain that for all $t\geq T$,
\begin{equation*}
	\begin{aligned}
			\mathbb{E}\left(\|u(\tau,\tau-t,u_{\tau-t})\|^4+\|v(\tau,\tau-t,v_{\tau-t})\|^4\right)\leq&1+27\varepsilon_2{(2\beta)}^{-1}\|\gamma\|^4_{L^\infty([\tau,T],\ell^2)}+18{(\varepsilon_3\beta)}^{-1}\|\chi\|_{L^\infty(\mathbb{R}, \ell^2)}^4\\&+\varepsilon_2\mathbb{E}\left(\int_{\tau-t}^{\tau}e^{2\beta(s-\tau)}\|g(s)\|^4ds\right).
	\end{aligned}
\end{equation*}
which along with \eqref{eq:2.26} completes the proof.

\label{lem:5.1}
	Suppose (A1)-(A3) hold. Then, for any $\mu_{1},\mu_{2}\in\mathcal{P}_2(\ell^2\times\ell^2)$ and $t\geq\tau$,
	\begin{align*}
	\mathbb{W}_2(p^*_{\tau,t}\mu_1,	p^*_{\tau,t}\mu_2)\leq a_1\mathbb{W}_2(\mu_{1},\mu_{2})e^{a_2(t-\tau)},
\end{align*}
where $a_1,a_2>0$ are two constants independent of $\tau$ and $t$.

Let $\Phi_1(t)=\binom{u_1(t,\tau,u_{1\tau})}{v_1(t,\tau,v_{1\tau})}$, $\Phi_{1\tau}=\binom{u_{1\tau}}{v_{1\tau}}$  with $\mathcal{L}_{u_{1\tau}}=\mu_{1}$ and $\Phi_2(t)=\binom{u_2(t,\tau,u_{2\tau})}{v_2(t,\tau,v_{2\tau})}$, $\Phi_{2\tau}=\binom{u_{2\tau}}{v_{2\tau}}$  with $\mathcal{L}_{u_{2\tau}}=\mu_{2}$ be two solutions of \eqref{eq:2.16}. Let $y(t)=u_1(t,\tau,u_{1\tau})-u_2(t,\tau,u_{2\tau})$,  $z(t)=v_1(t,\tau,v_{1\tau})-v_2(t,\tau,v_{2\tau})$ and  
	\begin{align*}
	\mathbb{W}_2(\mu_{1},\mu_{2})^2=\mathbb{E}\|u_{1\tau}-u_{2\tau}\|^2.
\end{align*}
Then, by \eqref{eq:2.16}, we have that for all $t\geq\tau$,
	\begin{align*}
	d(\Phi_1(t)-\Phi_2(t))=[F(\Phi_1(t))-F(\Phi_2(t))]dt+[G(\Phi_1(t))-G(\Phi_2(t))]dW(t).
\end{align*}
Following the It\^{o} formula, we get that for all $t\geq\tau$,
\begin{equation}
	\begin{aligned}
		\label{eq:5.4}
		&\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|y(t)\|^2+\|z(t)\|^2+\nu\|By(t)\|^2\right)+2\delta(\lambda+\delta^2-\alpha\delta)\mathbb{E}(\int_{\tau}^{t}\|y(s)\|^2ds)\\&+2\nu\delta\mathbb{E}(\int_{\tau}^{t}\|By(s)\|^2ds)+2(\alpha-\delta)\mathbb{E}(\int_{\tau}^{t}\|z(s)\|^2ds)
		\\=&\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|u_{1\tau}-u_{2\tau}\|^2+\|v_{1\tau}-v_{2\tau}\|^2+\nu\|B(u_{1\tau}-u_{2\tau})\|^2\right)\\&+2\mathbb{E}(\int_{\tau}^{t}(f(s,u_1(s),\mu_{1})-f(s,u_2(s),\mu_{2}),z(s))ds)\\&+\mathbb{E}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u_1(s),\mu_{1})-\tilde{\sigma}(s, u_2(s),\mu_{2})\|_{L_2(\ell^2,\ell^2)}^2ds).
	\end{aligned}
\end{equation}	
We estimate each term in the right-hand side of \eqref{eq:5.4}, respectively. For the second term, by \eqref{eq:2.3}, \eqref{eq:2.11} and \eqref{eq:2.8}, we have that
\begin{equation}
	\begin{aligned}
		\label{eq:5.5}
	&2\mathbb{E}(\int_{\tau}^{t}(f(s,u_1(s),\mu_{1})-f(s,u_2(s),\mu_{2}),z(s))ds)\\=&2\mathbb{E}(\int_{\tau}^{t}(f(s,u_1(s),\mu_{1})-f(s,u_2(s),\mu_{1}),z(s))ds)+2\mathbb{E}(\int_{\tau}^{t}(f(s,u_2(s),\mu_{1})-f(s,u_2(s),\mu_{2}),z(s))ds)\\\leq&2\mathbb{E}(\int_{\tau}^{t}\|\eta(s)\|\|y(s)\|\|z(s)\|ds)+\mathbb{E}(\int_{\tau}^{t}(\|z(s)\|^2+\|f(s,u_2(s),\mu_{1})-f(s,u_2(s),\mu_{2})\|^2)ds)\\\leq&2\mathbb{E}(\int_{\tau}^{t}\|\eta(s)\|\|y(s)\|\|z(s)\|ds)+\mathbb{E}(\int_{\tau}^{t}(\|z(s)\|^2+2\|\psi(s)\|^2\mathbb{E}\|y(s)\|^2)ds)\\\leq&(\|\eta\|^2_{L^\infty([\tau,T],\ell^2)}+2\|\psi\|^2_{L^\infty([\tau,T],\ell^2)})\int_{\tau}^{t}\mathbb{E}\|y(s)\|^2ds+2\int_{\tau}^{t}\mathbb{E}\|z(s)\|^2ds.
	\end{aligned}
\end{equation}
For the third term, by using \eqref{eq:2.12} and \eqref{eq:2.8}, we obtain
\begin{equation}
	\begin{aligned}
		\label{eq:5.6}
		\mathbb{E}(\int_{\tau}^{t}\|\tilde{\sigma}(s, u_1(s),\mu_{1})-\tilde{\sigma}(s, u_2(s),\mu_{2})\|_{L_2(\ell^2,\ell^2)}^2ds)\leq4\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)}\int_{\tau}^{t}\mathbb{E}\|y(s)\|^2ds.
	\end{aligned}
\end{equation}
It follows from \eqref{eq:5.4}-\eqref{eq:5.6}, we know that for all $t\geq\tau$
\begin{equation*}
	\begin{aligned}
		&\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|y(t)\|^2+\|z(t)\|^2+\nu\|By(t)\|^2\right)
		\\\leq&\mathbb{E}\left((\lambda+\delta^2-\alpha\delta)\|u_{1\tau}-u_{2\tau}\|^2+\|v_{1\tau}-v_{2\tau}\|^2+\nu\|B(u_{1\tau}-u_{2\tau})\|^2\right)\\&+(\|\eta\|^2_{L^\infty([\tau,T],\ell^2)}+2\|\psi\|^2_{L^\infty([\tau,T],\ell^2)}+4\|\kappa\|^2_{L^\infty(\mathbb{R},\ell^2)})\int_{\tau}^{t}\mathbb{E}\|y(s)\|^2ds+2\int_{\tau}^{t}\mathbb{E}\|z(s)\|^2ds,
	\end{aligned}
\end{equation*}	
which is
\begin{equation}
	\begin{aligned}
		\label{eq:5.7}
		\mathbb{E}\left(\|\Phi_1(t)-\Phi_2(t)\|^2\right)\leq a_1\mathbb{E}\left(\|\Phi_{1\tau}-\Phi_{2\tau}\|^2\right)+a_2\int_{\tau}^{t}\mathbb{E}\left(\|\Phi_1(s)-\Phi_2(s)\|^2\right)ds,
	\end{aligned}
\end{equation}
where $a_1,a_2>0$ are constants independent of $\tau$ and $t$.\par
Then using Gronwall's Lemma, we get that for all $t\geq\tau$,
\begin{align*}
	\mathbb{E}\left(\|\Phi_1(t)-\Phi_2(t)\|^2\right)\leq a_1\mathbb{E}\left(\|\Phi_{1\tau}-\Phi_{2\tau}\|^2\right)e^{a_2(t-\tau)}.
\end{align*}

\label{coro:5.1}
	Assume (A1)-(A3) hold. Let $S\subset\mathcal{P}_{4}(\ell^{2}\times\ell^{2})$ be a bounded set, i.e. there exists $R>0$ such that
\begin{align*}
	\int_{\ell^{2}\times\ell^{2}}\|x\|_{\ell^{2}\times\ell^{2}}^{4}\,\mathrm{d}\mu(x) \leq R \quad\text{for all }\mu\in S .
\end{align*}
	Then for every fixed $t\geq 0$ and every $\tau\in\mathbb{R}$, the mapping
\begin{align*}
	\Theta(t,\tau) : (S,d_{\mathcal{P}_{4}(\ell^{2}\times\ell^{2})})\longrightarrow(\mathcal{P}_{4}(\ell^{2}\times\ell^{2}),d_{\mathcal{P}_{4}(\ell^{2}\times\ell^{2})})
\end{align*}
is continuous. In other words, if $\{\mu_{n}\}_{n=1}^{\infty}\subset S$ satisfies
\begin{align*}
	d_{\mathcal{P}_{4}(\ell^{2}\times\ell^{2}}(\mu_{n},\mu)\longrightarrow 0\qquad (n\to\infty),
\end{align*}
	then
\begin{align*}
	d_{\mathcal{P}_{4}(\ell^{2}\times\ell^{2})}\left(\Phi(t,\tau)\mu_{n},	\Phi(t,\tau)\mu\right)\longrightarrow 0	\qquad (n\to\infty).
\end{align*}

Let $\{\mu_{n}\}_{n=1}^{\infty}\subset S$ be a sequence converging to $\mu\in S$ in $(\mathcal{P}_{4}(\ell^{2}\times\ell^{2}),d_{\mathcal{P}_{4}(\ell^{2}\times\ell^{2})})$. By Lemma \ref{lem:5.1}, for every $t\in\mathbb{R}^{+}$ and $\tau\in\mathbb{R}$,
\begin{equation}\label{eq:5.8}
	\mathbb{W}_{2}\left(p^{*}_{\tau,\tau+t}\mu_{n},	p^{*}_{\tau,\tau+t}\mu\right)\leq a_{1}\mathbb{W}_{2}(\mu_{n},\mu)\,e^{a_{2}t}.
\end{equation}
Since $\mathbb{W}_{2}(\mu_{n},\mu)\to 0$ as $n\to\infty$, inequality \eqref{eq:5.8} implies that
\begin{equation}\label{eq:5.9}
	\mathbb{W}_{2}\left(p^{*}_{\tau,\tau+t}\mu_{n},	p^{*}_{\tau,\tau+t}\mu\right)\longrightarrow 0,	\qquad n\to\infty.
\end{equation}

On the other hand, since $\mathbb{W}_{2}(\mu_{n},\mu)\to 0$, the sequence $\{\mu_{n}\}$ converges to $\mu$ weakly; hence by Skorokhod's representation theorem there exists a probability space $(\tilde\Omega,\tilde{\mathcal{F}},\tilde{\mathbb{P}})$ and $\ell^{2}\times\ell^{2}$-valued random variables
$\xi_{0},\xi_{n}\in L^{2}(\tilde\Omega,\tilde{\mathcal{F}},\tilde{\mathbb{P}};\ell^{2}\times\ell^{2})$ such that $\mathcal{L}_{\xi_{0}}=\mu$, $\mathcal{L}_{\xi_{n}}=\mu_{n}$ and
\begin{equation}\label{eq:5.10}
	\lim_{n\to\infty}\|\xi_{n}-\xi_{0}\|_{\ell^{2}\times\ell^{2}}=0,
	\qquad \tilde{\mathbb{P}}\text{-a.s.}.
\end{equation}
Because $\mu_{n}\in S$ for all $n$, there exists $R>0$ such that
\begin{align*}
\mathbb{E}^{\tilde{\mathbb{P}}}\|\xi_{n}\|_{\ell^{2}\times\ell^{2}}^{4}
= \int_{\ell^{2}\times\ell^{2}}\|x\|_{\ell^{2}\times\ell^{2}}^{4}\,\mathrm{d}\mu_{n}(x) \le R,
\qquad n\in\mathbb{N}^{+}.
\end{align*}
Thus $\{\xi_{n}\}_{n=1}^{\infty}$ is uniformly integrable in $L^{2}(\tilde\Omega,\ell^{2}\times\ell^{2})$.  Combining this with \eqref{eq:5.10} and applying Vitali's convergence theorem, we obtain 
\begin{align*}
\lim_{n\to\infty}
\mathbb{E}^{\tilde{\mathbb{P}}}\|\xi_{n}-\xi_{0}\|_{\ell^{2}\times\ell^{2}}^{2}=0.
\end{align*}
Consequently,
\begin{align*}
\mathbb{W}_{2}(\mu_{n},\mu)\leq \left(\mathbb{E}^{\tilde{\mathbb{P}}}\|\xi_{n}-\xi_{0}\|_{\ell^{2}\times\ell^{2}}^{2}\right)^{\frac{1}{2}}\longrightarrow 0,\qquad n\to\infty,
\end{align*}
which together with \eqref{eq:5.9} completes the proof.

\label{lem:5.2}
		Suppose (A1)-(A3), \eqref{eq:2.21}--\eqref{eq:2.26} hold. Given $\tau\in\mathbb{R}$, denote by
	\begin{align}\label{eq:5.11}
		K(\tau)=\left\{\mu\in\mathcal{P}_4(\ell^2\times\ell^2):\int_{\ell^{2}\times\ell^{2}}\|x\|_{\ell^{2}\times\ell^{2}}^{4}\,\mathrm{d}\mu(x)\leq L_4(\tau) \right\},
	\end{align}
	where $L_4(\tau)=L_3+L_3\int_{-\infty}^{\tau}e^{2\beta(s-\tau)}\|g(s)\|^4ds$, and $L_3$ is the same constant as in Lemma \ref{lem:4.4}, independent of $\tau$. Then $K=\{K(\tau):\tau\in\mathbb{R}\}\in\mathcal{D}$ is a closed $\mathcal{D}$-pullback absorbing set of $\Theta$.

By \eqref{eq:5.2} and Lemma \ref{lem:4.4}, we get that for each $\tau\in\mathbb{R}$
	and $D_2\in\mathcal{D}$, there exists $T = T (\tau, D_2) > 0$, such that for all $t\geq T$, it holds
	\begin{align}\label{eq:5.12}
		\Theta(t,\tau-t)D_2(\tau-t)\subseteq K(\tau).
	\end{align}
	Then by \eqref{eq:5.11} and \eqref{eq:2.26}, we see
	\begin{equation*}
		\begin{aligned}
			\lim_{\tau\rightarrow -\infty}e^{2\beta\tau}\|K(\tau)\|^4_{\mathcal{P}_4(\ell^2\times\ell^2)}=e^{2\beta\tau}L_3+L_3\int_{-\infty}^{\tau}e^{2\beta s}\|g(s)\|^4ds=0.
		\end{aligned}
	\end{equation*}
	which shows $K=\{K(\tau):\tau\in\mathbb{R}\}\in\mathcal{D}$. Combining this with \eqref{eq:5.12}, we infer that the set $K$ defined in \eqref{eq:5.11} indeed forms a closed $\mathcal{D}$-pullback absorbing set for $\Theta$.

Let $\tau\in\mathbb{R}$, $D\in\mathcal{D}$, $t_{n}\to\infty$ and $\mu_{n}\in D(\tau-t_{n})$. We prove that $\{\Theta(t_{n},\tau-t_{n})\mu_{n}\}_{n=1}^{\infty}$ has a convergent subsequence.

Without loss of generality, let $\Phi_{n}\in L^{4}(\Omega,\ell^{2}\times\ell^{2})$ with $\mathcal{L}_{\Phi_{n}}=\mu_{n}$. Denote by $\Phi(\tau,\tau-t_{n},\Phi_{n})=\Phi(\tau)=\binom{u(\tau)}{v(\tau)}$ the solution of \eqref{eq:2.16} with initial data $\Phi_{n}$ at time $\tau-t_{n}$. We first show that the distributions of $\{\Phi(\tau)\}_{n=1}^{\infty}$ are tight in $\ell^{2}\times\ell^{2}$.	

Let $\rho:\mathbb{Z}\to[0,1]$ be a smooth cut-off function such that $\rho(i)=1$ for $|i|\geq 2$ and $\rho(i)=0$ for $|i|\leq 1$. For $m\in\mathbb{N}^{+}$ define  $\theta_{m}(i)=\theta(\frac{i}{m})$, $i\in\mathbb{Z}$. Then decompose the solution as
\begin{equation}\label{eq:5.13}
\Phi(\tau)= \rho_{m}\,\Phi(\tau)+ (1-\rho_{m})\,\Phi(\tau).
	\end{equation}
By Lemma~\ref*{lem:4.2}, there exists $N_1=N_1(\tau,D)\in\mathbb N^+$ such that for all
$m\in\mathbb N^+$ and all $n\ge N_1$,
\begin{equation}\label{eq:5.14}
\mathbb E\|(1-\rho_m)\Phi(\tau)\|_{\ell^{2}\times\ell^{2}}^2
=\mathbb E\sum_{i\in\mathbb Z}(1-\rho_m(i))^2|(u_i(\tau)|^2+|v_i(\tau)|^2)\le C_1,
	\end{equation}
where $C_1=C_1(\tau)$ is independent of $n$ and $m$. By Chebyshev's inequality, for all $m\in\mathbb N^+$, $n\ge N_1$ and $R>0$,
\begin{equation}\label{eq:5.15}
\mathbb P\Bigl(\|(1-\rho_m)(u(\tau),v(\tau))\|_{\ell^{2}\times\ell^{2}}^2>R\Bigr)\le\frac{C_1}{R}.
	\end{equation}
Hence for any $\epsilon>0$, there exists $R(\epsilon,\tau)>0$ such that for all $m\in\mathbb N^+$ and $n\ge N_1$,
\begin{equation}\label{eq:5.16}
\mathbb P\Bigl(\|(1-\rho_m)(u(\tau),v(\tau))\|_{\ell^{2}\times\ell^{2}}>R(\epsilon,\tau)\Bigr)<\epsilon.
\end{equation}
For any fixed $m\in\mathbb N^+$, consider the closed subset of $\ell^{2}\times\ell^{2}$:
\begin{equation}\label{eq:5.17}
\mathcal Z_\epsilon:=\Bigl\{(w^{(1)},w^{(2)})\in\ell^{2}\times\ell^{2}:\|(w^{(1)},w^{(2)})\|_{\ell^{2}\times\ell^{2}}\le R(\epsilon,\tau),\ w^{(1)}_i=w^{(2)}_i=0\ \text{for}\ |i|>2m\Bigr\}.
\end{equation}
We claim $\mathcal Z_\epsilon$ is compact in $\ell^{2}\times\ell^{2}$. Indeed, restricting $w=(w^{(1)},w^{(2)})$ to $\{|i|\le 2m\}$, we obtain $w|_{\{|i|\le 2m\}}\in\widehat{\mathcal Z}_\epsilon$, where
\begin{equation*}
\widehat{\mathcal Z}_\epsilon
:=\Bigl\{\bigl(w^{(1)}_i,w^{(2)}_i\bigr)_{|i|\le 2m}\in\mathbb R^{2(2m+1)}:
\sum_{|i|\le 2m}|w^{(1)}_i|^2+|w^{(2)}_i|^2\le R^2(\epsilon,\tau)\Bigr\},
\end{equation*}
and $\widehat{\mathcal Z}_\epsilon$ is bounded, hence relatively compact in $\mathbb R^{2(2m+1)}$.
By the natural identification $\mathcal Z_\epsilon\cong\widehat{\mathcal Z}_\epsilon$,
$\mathcal Z_\epsilon$ is compact in $\ell^{2}\times\ell^{2}$. From \eqref{eq:5.16} we obtain, for all $m\in\mathbb N^+$ and $n\ge N_1$,
\begin{equation}\label{eq:5.18}
\mathbb P\Bigl((1-\rho_m)\Phi(\tau)\in\mathcal Z_\epsilon\Bigr)>1-\epsilon.
\end{equation}
Since $\epsilon>0$ is arbitrary, \eqref{eq:5.18} implies that for each $m\in\mathbb N^+$,
\begin{equation}\label{eq:5.19}
\Bigl\{\mathcal L_{(1-\rho_m)\Phi(\tau,\tau-t_{n},\Phi_{n})}\Bigr\}_{n=N_1}^\infty
\ \text{is tight in}\ \mathcal P(\ell^{2}\times\ell^{2}).
\end{equation}	

By Lemma~\ref*{lem:4.3} (uniform tail estimate), for every $\varepsilon>0$ there exist
$N_2=N_2(\varepsilon,\tau,D)\in\mathbb N^+$ and $m_0=m_0(\varepsilon,\tau,D)\in\mathbb N^+$ such that for all $n\ge N_2$,
\begin{equation}\label{eq:5.20}
\mathbb E\|\rho_{m_0}(u(\tau),v(\tau))\|_{\ell^{2}\times\ell^{2}}^2
=\mathbb E\sum_{|i|\ge 2m_0}|u_i(\tau)|^2+|v_i(\tau)|^2
<\frac{\varepsilon^2}{9}.
\end{equation}	
From \eqref{eq:5.19}, the sequence $\bigl\{\mathcal L_{(1-\rho_{m_0})(u_n(\tau),v_n(\tau))}\bigr\}_{n=N_2}^\infty$ is tight in $\mathcal P(\ell^{2}\times\ell^{2})$, hence relatively compact by Prokhorov.
Therefore there exist $n_1,\ldots,n_l\ge N_2$ such that
\begin{equation}\label{eq:5.21}
\bigcup_{n=N_2}^\infty
\mathcal L_{(1-\rho_{m_0})(u_n(\tau),v_n(\tau))}
\subseteq
\bigcup_{j=1}^l
\mathcal B\!\Bigl(\mathcal L_{(1-\rho_{m_0})(u_{n_j}(\tau),v_{n_j}(\tau))},\frac{\varepsilon}{3}\Bigr).
\end{equation}
Consequently, for any $n\ge N_2$, there exists $j_0\in\{1,\ldots,l\}$ such that
\begin{equation}\label{eq:5.22}
d_{\mathcal P(\ell^{2}\times\ell^{2}}
\Bigl(\mathcal L_{(1-\rho_{m_0})(u_n(\tau),v_n(\tau))},
\mathcal L_{(1-\rho_{m_0})(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))}\Bigr)
<\frac{\varepsilon}{3}.
\end{equation}

Now use the definition of the Wasserstein distance and bounded Lipschitz functions. For any $\psi\in\mathrm{Lip}_b(\ell^{2}\times\ell^{2})$ with $\|\psi\|_{\mathrm{Lip}}\le1$, we have
\begin{align*}
	&d_{\mathcal P(\ell^{2}\times\ell^{2})}
	\Bigl(\mathcal L_{(u(\tau),v(\tau))},
	\mathcal L_{(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))}\Bigr) \\[4pt]
	&\ \le
	\mathbb E\Bigl|\psi(u(\tau),v(\tau))
	-\psi\bigl((1-\rho_{m_0})(u(\tau),v(\tau))\bigr)\Bigr|
	\\[4pt]
	&\ \ +\mathbb E\Bigl|\psi\bigl((1-\rho_{m_0})(u(\tau),v(\tau))\bigr)
	-\psi\bigl((1-\rho_{m_0})(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))\bigr)\Bigr|
	\\[4pt]
	&\ \ +\mathbb E\Bigl|\psi\bigl((1-\rho_{m_0})(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))\bigr)
	-\psi(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))\bigr)\Bigr| \\[4pt]
	&\ \le
	\mathbb E\|\rho_{m_0}(u(\tau),v(\tau))\|_{\ell^{2}\times\ell^{2}}
	+\mathbb E\|\rho_{m_0}(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))\|_{\ell^{2}\times\ell^{2})}
	\\[4pt]
	&\ \ +d_{\mathcal P(\ell^{2}\times\ell^{2})}
	\Bigl(\mathcal L_{(1-\rho_{m_0})(u(\tau),v(\tau))},
	\mathcal L_{(1-\rho_{m_0})(u_{n_{j_0}}(\tau),v_{n_{j_0}}(\tau))}\Bigr) \\[4pt]
	&\ \ <\frac{\varepsilon}{3}+\frac{\varepsilon}{3}+\frac{\varepsilon}{3}
	=\varepsilon,
\end{align*}
where we used $|\psi(a)-\psi(b)|\le\|a-b\|_{\ell^{2}\times\ell^{2}}$ (since $\|\psi\|_{\mathrm{Lip}}\le1$)
and \eqref{eq:5.20}, \eqref{eq:5.22}.
Since $\varepsilon>0$ is arbitrary, this shows
\begin{equation}\label{eq:5.23}
\Bigl\{\mathcal L_{(u_n(\tau),v_n(\tau))}\Bigr\}_{n=1}^\infty \ \text{is tight in}\ \mathcal P(\ell^{2}\times\ell^{2}).
\end{equation}
Hence there exists $\varpi\in\mathcal P(\ell^{2}\times\ell^{2})$ such that, up to a subsequence,
\begin{equation}\label{eq:5.24}
\mathcal L_{\Phi(\tau,\tau-t_{n},\Phi_{n})}\rightharpoonup\varpi\qquad(n\to\infty).
\end{equation}

It remains to show that $\varpi\in\mathcal P_4(\ell^{2}\times\ell^{2})$. Let  $K=\{K(\tau):\tau\in\mathbb R\}$ be the closed $\mathcal D$-pullback absorbing set
given by Lemma~\ref*{lem:5.2}. Since $D\in\mathcal D$, there exists $N_3=N_3(\tau,D)\in\mathbb N^+$ such that for all $n\ge N_3$,
\begin{equation}\label{eq:5.25}
\mathcal L_{\Phi(\tau)}\in K(\tau).
\end{equation}
Because $K(\tau)$ is closed in $\mathcal P_4(\ell^{2}\times\ell^{2})$ and the convergence in \eqref{eq:5.24} is weak convergence in $\mathcal P(\ell^{2}\times\ell^{2})$, \eqref{eq:5.25} implies
$\varpi\in K(\tau)\subset\mathcal P_4(\ell^{2}\times\ell^{2})$. Thus $\varpi\in\mathcal P_4(\ell^{2}\times\ell^{2})$, which completes the proof.

\label{lem:6.1}
Assume that \eqref{eq:6.1}--\eqref{eq:6.2} hold. Then for every  $\tau\in\mathbb R$, $T>0$ and $R>0$, the solutions of \eqref{eq:6.3} and \eqref{eq:6.4} satisfy
\begin{align}\label{eq:6.6}
	\lim_{\varepsilon\to0^{+}}
	\sup_{\|\Phi_{\tau}\|_{L^2(\Omega,\ell^2\times\ell^2)}^2\le R}
	\sup_{\tau\le t\le \tau+T}
	\mathbb E\Bigl(\bigl\|\Phi^{\varepsilon}(t,\tau,\Phi_{\tau})
	-\Phi(t,\tau,\Phi_{\tau})\bigr\|_{\ell^2\times\ell^2}^2\Bigr)=0.
\end{align}

Let $w(t)=u^{\varepsilon}(t)-u(t)$ and $z(t)=v^{\varepsilon}(t)-v(t)$. From \eqref{eq:6.3} and \eqref{eq:6.4} we obtain that for all $t>\tau$,
\begin{align*}
	d(\Phi^{\varepsilon}(t)-\Phi(t))=[F(\Phi^{\varepsilon}(t))-F(\Phi(t))]dt+[G(\Phi^{\varepsilon}(t))-G(\Phi(t))]dW(t).
\end{align*}
By the It\^{o} formula, taking the expectation, we get that for all $t\ge\tau$,
\begin{equation}
	\begin{aligned}
		\label{eq:6.7}
		\mathbb{E}\bigl\|\Phi^{\varepsilon}(t)
		-\Phi(t)\bigr\|^2
		\le&2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-f(s,u(s)),z(s))ds)\\&+\mathbb{E}(\int_{\tau}^{t}\|\sigma^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-\sigma(s, u(s))\|_{L_2(\ell^2,\ell^2)}^2ds).
	\end{aligned}
\end{equation}	
We estimate each term in the right-hand side of \eqref{eq:6.7}, respectively. For the first term,  we have that
\begin{equation*}
	\begin{aligned}
		&2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-f(s,u(s)),z(s))ds)
		\\=&2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-f^{\varepsilon}(s,u(s),L_{u^{\varepsilon}(s)}),z(s))ds)
		\\&+2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u(s),L_{u^{\varepsilon}(s)})-f^{\varepsilon}(s,u(s),L_{u(s)}),z(s))ds)
		\\&+2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u(s),L_{u(s)})-f(s,u(s)),z(s))ds).
	\end{aligned}
\end{equation*}
Along with \eqref{eq:2.2}, \eqref{eq:2.3}, \eqref{eq:2.8} and \eqref{eq:6.1}, we obtain that
\begin{equation}
	\begin{aligned}
		\label{eq:6.8}
		&2\mathbb{E}(\int_{\tau}^{t}(f^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-f(s,u(s)),z(s))ds)
		\\\le&2\mathbb{E}(\int_{\tau}^{t}\|\eta(s)\|\|w(s)\|\|z(s)\|ds)
		+2\mathbb{E}(\int_{\tau}^{t}\sum_{i \in \mathbb{Z}}\varphi_i(s)(\mathbb{E}\left|w_i(s)\right|^2)^\frac{1}{2}\left|z_i(s)\right|ds)
		\\&+2\varepsilon\mathbb{E}(\int_{\tau}^{t}\sum_{i \in \mathbb{Z}}\tilde{\varphi}_i(s)(\left|u_i(s)\right|+(\mathbb{E}\left|w_i(s)\right|^2)^\frac{1}{2})\left|z_i(s)\right|ds)
		\\\le&\|\eta\|_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}(\|w(s)\|^2+\|z(s)\|^2)ds
		+2\|\varphi\|_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}(\|w(s)\|^2+\|z(s)\|^2)ds
		\\&+2\varepsilon\mathbb{E}(\int_{\tau}^{t}\|\tilde{\varphi}(s)\|(\|u(s)\|^2+\mathbb{E}\|u(s)\|^2)ds)+\varepsilon\mathbb{E}(\int_{\tau}^{t}\|\tilde{\varphi}(s)\|\|z(s)\|^2ds)
		\\\le&(\|\eta\|_{L^\infty([\tau,T],\ell^2)}+\|\varphi\|_{L^\infty([\tau,T],\ell^2)}+\varepsilon\|\tilde{\varphi}\|_{L^\infty([\tau,T],\ell^2)})\mathbb{E}(\int_{\tau}^{t}\bigl\|\Phi^{\varepsilon}(s)
		-\Phi(s)\bigr\|^2ds)
		\\&+\|\tilde{\varphi}\|_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}\|u(s)\|^2ds.
	\end{aligned}
\end{equation}
For the second term, on the right-hand side of \eqref{eq:6.7}, we have that
\begin{equation*}
	\begin{aligned}
		&\mathbb{E}(\int_{\tau}^{t}\|\sigma^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-\sigma(s, u(s))\|_{L_2(\ell^2,\ell^2)}^2ds)
		\\\le&\mathbb{E}(\int_{\tau}^{t}\|\sigma^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-\sigma^{\varepsilon}(s, u(s),\mathcal L_{u(s)})\|_{L_2(\ell^2,\ell^2)}^2ds)
		\\&+\mathbb{E}(\int_{\tau}^{t}\|\sigma^{\varepsilon}(s, u(s),\mathcal L_{u(s)})-\sigma(s,u(s))\|_{L_2(\ell^2,\ell^2)}^2ds).
	\end{aligned}
\end{equation*}
By \eqref{eq:2.12}, \eqref{eq:2.8} and \eqref{eq:6.5}, we obtain that
\begin{equation}
	\begin{aligned}
		\label{eq:6.9}
		&\mathbb{E}(\int_{\tau}^{t}\|\sigma^{\varepsilon}(s,u^{\varepsilon}(s),\mathcal L_{u^{\varepsilon}(s)})-\sigma(s, u(s))\|_{L_2(\ell^2,\ell^2)}^2ds)
		\\\le&2\mathbb{E}(\int_{\tau}^{t}\|\kappa(s)\|^2(\|w(s)\|^2+\mathbb{E}\|w(s)\|^2)ds)+2\varepsilon^2\mathbb{E}(\int_{\tau}^{t}\|\tilde\psi(s)\|^2(\|u(s)\|^2+\mathbb{E}\|u(s)\|^2)ds)
		\\\le&4\|\kappa\|^2_{L^\infty(\mathbb R,\ell^2)}\mathbb{E}(\int_{\tau}^{t}\bigl\|\Phi^{\varepsilon}(s)
		-\Phi(s)\bigr\|^2ds)
		+4\varepsilon^2\|\tilde\psi\|^2_{L^\infty([\tau,T],\ell^2)}\int_{\tau}^{t}\mathbb{E}\|u(s)\|^2ds.
	\end{aligned}
\end{equation}
Thus, from \eqref{eq:6.7}-\eqref{eq:6.9}, there exist constants $C_2$ and $C_3$ such that
\begin{equation*}
	\begin{aligned}
		\mathbb{E}\bigl\|\Phi^{\varepsilon}(t)
		-\Phi(t)\bigr\|^2
		\le C_2\mathbb{E}(\int_{\tau}^{t}\bigl\|\Phi^{\varepsilon}(s)
		-\Phi(s)\bigr\|^2ds)+\varepsilon C_3\int_{\tau}^{t}\mathbb{E}\|u(s)\|^2ds.
	\end{aligned}
\end{equation*}
Then by Lemma \ref{lem:4.2}, we know that for all $t\in[\tau,\tau+T]$ and $\varepsilon\in(0,1)$,
\begin{equation*}
	\begin{aligned}
		\mathbb{E}\bigl\|\Phi^{\varepsilon}(t)
		-\Phi(t)\bigr\|^2
		\le C_2\mathbb{E}(\int_{\tau}^{t}\bigl\|\Phi^{\varepsilon}(s)
		-\Phi(s)\bigr\|^2ds)+\varepsilon C_3C_4(1+\|\Phi_{\tau}\|_{L_2(\Omega,\ell^2\times\ell^2)}^2)T,
	\end{aligned}
\end{equation*}
where $C_4=C_4(\tau,T)>0$ is a constant independent of $\varepsilon$. Then by Gronwall's inequality, we have for all $t\in[\tau,\tau+T]$ and $\varepsilon\in(0,1)$ and $\|\Phi_{\tau}\|_{L_2(\Omega,\ell^2\times\ell^2)}\le R$,
\begin{equation*}
	\begin{aligned}
		\mathbb{E}\bigl\|\Phi^{\varepsilon}(t)
		-\Phi(t)\bigr\|^2
		\le \varepsilon C_3C_4(1+R^2)e^{C_2 T} ,
	\end{aligned}
\end{equation*}
which concludes the proof.

\label{coro:6.1}
	Assume that \eqref{eq:6.1}--\eqref{eq:6.2} hold.
	Then for every $t\in\mathbb R^+$, $\tau\in\mathbb R$ and $R>0$,
	\begin{align}\label{eq:6.10}
		\lim_{\varepsilon\to0^{+}}
		\sup_{\substack{\mu\in\mathcal P_4(\ell^2\times\ell^2)\\
				\mu(\|\cdot\|^2)\le R}}
		\mathbb W_2\bigl(\Theta^{\varepsilon}(t,\tau)\mu,\Theta(t,\tau)\mu\bigr)=0,
	\end{align}
	and hence
	\begin{align}\label{eq:6.11}
		\lim_{\varepsilon\to0^{+}}
		\sup_{\substack{\mu\in\mathcal P_4(\ell^2\times\ell^2)\\
				\mu(\|\cdot\|^2)\le R}}
		d_{\mathcal P(\ell^2\times\ell^2)}\bigl(\Theta^{\varepsilon}(t,\tau)\mu,
		\Theta(t,\tau)\mu\bigr)=0.
	\end{align}

\label{th:6.1}
	Assume that \eqref{eq:6.1}--\eqref{eq:6.2} hold.
	Then for every $\tau\in\mathbb R$,
	\begin{align}\label{eq:6.12}
		\lim_{\varepsilon\to0^{+}}
		d_{\mathcal P_4(\ell^2\times\ell^2)}\!\bigl(\mathcal A^{\varepsilon}(\tau),\,
		\mathcal A(\tau)\bigr)=0,
	\end{align}
	where $d_{\mathcal P_4(\ell^2\times\ell^2)}(\cdot,\cdot)$ denotes the Hausdorff
	semi-distance in $\mathcal P_4(\ell^2\times\ell^2)$.

Since $f^{\varepsilon}, g^{\varepsilon}, \sigma^{\varepsilon}$ and $f, g, \sigma$ satisfy (A1)--(A3) uniformly with respect to $\varepsilon \in (0, 1)$, we have that the family $K = \{ K(\tau) : \tau \in \mathbb{R} \}$ given by Lemma \ref{lem:5.2} is a closed $\mathcal{D}$-pullback absorbing set of $\Theta$ and $\Theta^{\varepsilon}$ for all $\varepsilon \in (0, 1)$. In particular, for every $\tau \in \mathbb{R}$, $\mathcal{A}(\tau)$ and $\mathcal{A}^{\varepsilon}(\tau)$ are subsets of $K(\tau)$ for all $\varepsilon \in (0, 1)$.

Since $\mathcal{A}$ is the $\mathcal{D}$-pullback measure attractor of $\Phi$ in $(\mathcal{P}_4(\ell^2\times\ell^2), d_{\mathcal{P}(\ell^2\times\ell^2)})$, we obtain that for every $\varpi > 0$, there exists $T = T(\varpi, \tau, K) > 0$ such that	
\begin{align}\label{eq:6.13}
	d_{\mathcal P_4(\ell^2\times\ell^2)}\!
	\bigl(\Theta(T,\tau-T)K(\tau-T),\;\mathcal A(\tau)\bigr)<\frac{\varpi}{2}.
\end{align}
By Corollary \ref{coro:6.1}, there exists $\hat \varepsilon\in(0,1)$ such that
for all $\varepsilon\in(0,\hat \varepsilon)$,
\begin{align}\label{eq:6.14}
	\sup_{\mu\in K(\tau-T)}
	d_{\mathcal P_4(\ell^2\times\ell^2)}\!
	\bigl(\Theta^{\varepsilon}(T,\tau-T)\mu,\;\Theta(T,\tau-T)\mu\bigr)
	<\frac{\varpi}{2}.
\end{align}
From \eqref{eq:6.13} and \eqref{eq:6.14} we obtain
\begin{align}\label{eq:6.15}
	\sup_{\mu\in\mathcal A^{\varepsilon}(\tau-T)}
	d_{\mathcal P_4(\ell^2\times\ell^2)}\!
	\bigl(\Theta^{\varepsilon}(T,\tau-T)\mu,\;\mathcal A(\tau)\bigr)<\varpi,
	\qquad\forall\,\varepsilon\in(0,\hat \varepsilon).
\end{align}
 By the invariance of $\mathcal A^{\varepsilon}$,
$\mathcal A^{\varepsilon}(\tau)=\Theta^{\varepsilon}(T,\tau-T)\mathcal A^{\varepsilon}(\tau-T)$,
and \eqref{eq:6.15} imply
\begin{align}\label{eq:6.16}
	\sup_{\mu\in\mathcal A^{\varepsilon}(\tau)}
	d_{\mathcal P_4(\ell^2\times\ell^2)}\!
	\bigl(\mu,\;\mathcal A(\tau)\bigr)<\varpi,
	\qquad\forall\,\varepsilon\in(0,\hat \varepsilon).
\end{align}
Thus $\lim\limits_{\varepsilon\to0^{+}}
d_{\mathcal P_4(\ell^2\times\ell^2)}(\mathcal A^{\varepsilon}(\tau),\mathcal A(\tau))=0$.

Finally, combining Theorem \ref{th5.4} (attractor existence) and
Theorem \ref{th:6.1} (upper semicontinuity), when both attractors are singletons,
we immediately obtain the convergence of invariant measures.

\begin{Corollary}\label{coro:7.2}
Under the hypotheses of Theorems \ref{th5.4} and \ref{th:6.1},
if $f^{\varepsilon}$, $\sigma^{\varepsilon}$, $f$ and $\sigma$ are all time-independent,
then the unique invariant measure $\mu^{\varepsilon}$ of \eqref{eq:1.2} converges to the unique
invariant measure $\mu$ of \eqref{eq:1.3} in $\mathcal P_4(\ell^2\times\ell^2)$:
\begin{align}\label{eq:6.17}
\lim_{\varepsilon\to0^{+}}d_{\mathcal P_4(\ell^2\times\ell^2)}(\mu^{\varepsilon},\mu)=0.
\end{align}
\end{Corollary}

\label{coro:7.2}
Under the hypotheses of Theorems \ref{th5.4} and \ref{th:6.1},
if $f^{\varepsilon}$, $\sigma^{\varepsilon}$, $f$ and $\sigma$ are all time-independent,
then the unique invariant measure $\mu^{\varepsilon}$ of \eqref{eq:1.2} converges to the unique
invariant measure $\mu$ of \eqref{eq:1.3} in $\mathcal P_4(\ell^2\times\ell^2)$:
\begin{align}\label{eq:6.17}
\lim_{\varepsilon\to0^{+}}d_{\mathcal P_4(\ell^2\times\ell^2)}(\mu^{\varepsilon},\mu)=0.
\end{align}
